// Üretilen dosya: tool/ozgun/uret.py. Kimya · Maddenin halleri, karışımlar, çözeltiler (orta).
const ozChemistry2Orta = <(String, String, List<String>, String)>[
  ('Bir maddenin hâl değiştirmesi sırasında aşağıdakilerden hangisi değişmez?', 'Moleküllerin kimyasal yapısı', ['Tanecikler arası uzaklık', 'Taneciklerin düzenliliği', 'Maddenin birim hacimdeki kütlesi'], 'Hâl değişimi fiziksel bir olaydır; tanecikler arası düzen ve uzaklık değişir ama moleküllerin kendisi ve bileşimi değişmez.'),
  ('Bir katı ısıtıldığında belirli bir sıcaklıkta değil, geniş bir sıcaklık aralığında yavaş yavaş yumuşayarak akışkanlaşıyor. Bu katı için en olası yorum hangisidir?', 'Amorf yapıdadır', ['İyonik kristaldir', 'Metalik kristaldir', 'Kovalent ağ kristalidir'], 'Amorf katılarda tanecikler arası etkileşimler eşit değildir; bu yüzden keskin bir erime noktası yerine bir yumuşama aralığı gösterirler.'),
  ('Kuvars kristali ile kuvars camı aynı bileşime (SiO₂) sahiptir. İkisi arasındaki fark nedir?', 'Kuvars camında düzenli örgü yapısı bulunmaz', ['Kuvars camında silisyum bulunmaz', 'Kuvars kristali bir karışımdır', 'Kuvars camı bir sıvıdır'], 'Kuvars kristalinde SiO₄ birimleri düzenli bir örgü oluşturur; eriyiğin hızlı soğutulmasıyla elde edilen kuvars camında bu düzen yoktur.'),
  ('Kırıldığında düzgün yüzeyler boyunca ayrılan, keskin erime noktasına sahip bir katının yapısı için ne söylenebilir?', 'Kristal yapıdadır', ['Amorf yapıdadır', 'Bir koloiddir', 'Bir alaşım olmak zorundadır'], 'Düzgün yüzeyler boyunca dilinim ve keskin erime noktası, taneciklerin düzenli bir örgüde dizildiği kristal katıların belirtisidir.'),
  ('Aşağıdaki katılardan hangisi amorf değildir?', 'Şeker kristali', ['Kauçuk', 'Pamuk şekeri', 'Volkanik cam olan obsidyen'], 'Toz ya da küp şeker kristal yapılıdır. Kauçuk, eritilip hızla soğutulan şekerden yapılan pamuk şekeri ve volkanik cam obsidyen amorftur.'),
  ('Eriyik hâlindeki bir maddenin çok hızlı soğutulması, oluşan katının hangi yapıda olma olasılığını artırır?', 'Amorf', ['Kristal', 'İyonik', 'Metalik'], 'Hızlı soğumada tanecikler düzenli konumlarına yerleşmeye zaman bulamaz ve düzensiz amorf yapı oluşur; yavaş soğuma ise iri kristallerin oluşmasını kolaylaştırır.'),
  ('Katı hâlde elektriği iletmeyen, ancak eritildiğinde ya da suda çözündüğünde elektriği ileten yüksek erime noktalı katı hangi türdendir?', 'İyonik katı', ['Metalik katı', 'Moleküler katı', 'Amorf polimer'], 'İyonik katılarda iyonlar örgüde sabittir; eriyik ya da sulu çözeltide iyonlar serbestçe hareket edebildiği için akım iletilir.'),
  ('Elmasın çok sert olması ve çok yüksek sıcaklıklarda erimesi hangi katı türüne ait olmasından kaynaklanır?', 'Kovalent ağ katısı', ['Moleküler katı', 'İyonik katı', 'Metalik katı'], 'Elmasta her karbon atomu dört komşusuna kovalent bağla bağlıdır ve bütün kristal dev bir ağ oluşturur; bu ağı bozmak çok enerji gerektirir.'),
  ('Kuru buz (katı CO₂) hangi tür kristal katıya örnektir?', 'Moleküler katı', ['Kovalent ağ katısı', 'İyonik katı', 'Metalik katı'], 'Kuru buzun örgü noktalarında CO₂ molekülleri bulunur ve bunlar zayıf moleküller arası kuvvetlerle bir arada tutulur; bu yüzden kolay süblimleşir.'),
  ('Grafitin kurşun kalem ucu olarak kullanılabilmesi yapısının hangi özelliğiyle ilgilidir?', 'Katmanların birbiri üzerinde kolayca kayabilmesi', ['Çok düşük erime noktasına sahip olması', 'Suda kolayca çözünmesi', 'Katmanların birbirine kovalent bağlarla sıkıca bağlı olması'], 'Grafitte karbon atomları düzlemsel katmanlar oluşturur; katmanlar arası etkileşim zayıf olduğundan katmanlar kayar ve kâğıtta iz bırakır.'),
  ('Gliserinin (üç –OH grubu taşır) etanolden (bir –OH grubu taşır) çok daha viskoz olmasının başlıca nedeni nedir?', 'Daha fazla hidrojen bağı kurabilmesi', ['Daha düşük mol kütlesine sahip olması', 'Apolar bir molekül olması', 'Daha yüksek buhar basıncına sahip olması'], 'Gliserin molekülü üç –OH grubuyla komşularına çok sayıda hidrojen bağı yapar; güçlü etkileşim moleküllerin birbiri üzerinden kaymasını zorlaştırır.'),
  ('Viskozite ile ilgili aşağıdaki ifadelerden hangisi doğrudur?', 'Moleküller arası çekim arttıkça genellikle artar', ['Sıcaklık arttıkça her sıvıda artar', 'Yalnız katılar için tanımlanır', 'Molekülün boyutundan ve şeklinden hiç etkilenmez'], 'Güçlü moleküller arası etkileşimler ve uzun, birbirine dolanabilen moleküller viskoziteyi artırır; sıvılarda sıcaklık artışı ise viskoziteyi azaltır.'),
  ('Sıvı damlalarının küresel şekil almaya eğilimli olmasının nedeni nedir?', 'Küre, belirli hacim için en küçük yüzey alanına sahip şekildir', ['Küre en büyük yüzey alanını sağlar', 'Damlalar içinde hava bulunur', 'Yerçekimi damlayı yuvarlar'], 'Yüzey gerilimi sıvıyı yüzey alanını küçültmeye zorlar; belirli bir hacmi en az yüzeyle saran geometrik şekil küredir.'),
  ('Suya bulaşık deterjanı eklendiğinde su yüzeyinde yüzen iğnenin battığı görülür. Bunun nedeni nedir?', 'Deterjanın suyun yüzey gerilimini azaltması', ['Deterjanın suyun yoğunluğunu azaltması', 'Deterjanın iğneyi paslandırması', 'Deterjanın suyun viskozitesini sıfırlaması'], 'Deterjan molekülleri yüzeye yerleşip su molekülleri arasındaki yüzey çekimini zayıflatır; gergin zar etkisi kaybolunca iğne batar.'),
  ('Kılcal borudaki su yükselmesi ile ilgili hangisi doğrudur?', 'Boru inceldikçe su daha yükseğe çıkar', ['Boru kalınlaştıkça su daha yükseğe çıkar', 'Boru çapı yükselmeyi etkilemez', 'Su yalnız plastik borularda yükselir'], 'Yükselme yüksekliği boru yarıçapı ile ters orantılıdır; ince borularda yapışma etkisi su sütununun ağırlığına göre daha baskın olur.'),
  ('Sıcaklık arttıkça bir sıvının yüzey gerilimi nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce azalır sonra sıfırın altına iner'], 'Sıcaklık artınca moleküllerin kinetik enerjisi yükselir ve aralarındaki çekim etkisi zayıflar; bu da yüzey gerilimini azaltır.'),
  ('Bir sıvının buhar basıncı aşağıdakilerden hangisine bağlıdır?', 'Sıcaklığa', ['Kaptaki sıvı miktarına', 'Kabın hacmine', 'Sıvının yüzey alanına'], 'Denge buhar basıncı yalnız sıvının türüne ve sıcaklığa bağlıdır; sıvı miktarı, kap hacmi ya da yüzey alanı dengeye ulaşma süresini etkiler ama değeri değiştirmez.'),
  ('Aynı sıcaklıkta dietil eterin buhar basıncı sudan çok yüksektir. Bu durum aşağıdakilerden hangisini gösterir?', 'Eter moleküllerinin birbirini daha zayıf çektiğini', ['Eterin sudan daha yüksek sıcaklıkta kaynadığını', 'Eter moleküllerinin hidrojen bağı yaptığını', 'Eterin daha viskoz olduğunu'], 'Moleküller arası çekim zayıf olan sıvıda moleküller sıvıdan daha kolay kopar ve buhar basıncı yüksek olur. Eter molekülleri arasında hidrojen bağı yoktur.'),
  ('Açık bir kaptaki suyun buharlaşmasının kapalı kaptakinden farkı nedir?', 'Açık kapta buhar uzaklaştığı için denge kurulamaz', ['Açık kapta su hiç buharlaşmaz', 'Kapalı kapta buharlaşma hiç durmaz ve sıvı tükenir', 'Açık kapta buhar basıncı sıcaklıktan bağımsızdır'], 'Açık kapta buhar ortamdan uzaklaşır, yoğuşma buharlaşmayı dengeleyemez ve sıvı zamanla tükenir. Kapalı kapta ise dinamik denge kurulur.'),
  ('Buharlaşma ve buhar basıncıyla ilgili hangisi yanlıştır?', 'Buharlaşma yalnız kaynama noktasında olur', ['Buharlaşma sıvı yüzeyinde gerçekleşir', 'Buharlaşma her sıcaklıkta olabilir', 'Buharlaşma ısı alan bir süreçtir'], 'Buharlaşma, kaynama noktasının altındaki her sıcaklıkta yüzeydeki enerjisi yüksek moleküllerin kopmasıyla gerçekleşir. Kaynama ise sıvının her yerinde olur.'),
  ('Düdüklü tencerede yemeklerin daha çabuk pişmesinin nedeni nedir?', 'Artan iç basıncın suyun kaynama sıcaklığını yükseltmesi', ['Tencerenin suyun buharlaşmasını tümüyle durdurması', 'Basıncın suyun özgül ısısını sıfırlaması', 'Kapağın ısıyı yansıtarak suyu dondurması'], 'Kapalı tencerede buhar birikerek basıncı yükseltir; su yaklaşık 115–120 °C\'ye kadar sıvı kalır ve yüksek sıcaklık pişirmeyi hızlandırır.'),
  ('Aynı ortamda kaynama noktaları 35 °C, 65 °C, 78 °C ve 100 °C olan dört sıvıdan hangisinin 25 °C\'deki buhar basıncı en büyüktür?', 'Kaynama noktası 35 °C olan', ['Kaynama noktası 65 °C olan', 'Kaynama noktası 78 °C olan', 'Kaynama noktası 100 °C olan'], 'Aynı dış basınçta en düşük sıcaklıkta kaynayan sıvı, buhar basıncı dış basınca en kolay ulaşan, yani her sıcaklıkta buhar basıncı en yüksek olan sıvıdır.'),
  ('Buharlaşma ile kaynama arasındaki farklardan biri hangisidir?', 'Kaynama sıvının her yerinde, buharlaşma yalnız yüzeyde olur', ['Buharlaşma yalnız 100 °C\'de olur', 'Kaynama sırasında sıcaklık sürekli artar', 'Buharlaşma ısı veren bir olaydır'], 'Buharlaşma her sıcaklıkta yüzeyden gerçekleşir; kaynamada buhar basıncı dış basınca eşitlendiği için kabarcıklar sıvının iç kısımlarında da oluşur.'),
  ('Buzun erime ısısı 334 J/g\'dır. 0 °C\'deki 50 g buzun tamamını 0 °C\'de suya dönüştürmek için kaç kJ ısı gerekir?', '16,7', ['6,68', '33,4', '167'], 'Q = m · L = 50 g · 334 J/g = 16 700 J = 16,7 kJ. Sıcaklık sabit kaldığı için yalnız erime ısısı hesaba girer.'),
  ('Kış aylarında meyve depolarına içi su dolu kovalar konmasının amacı nedir?', 'Donan suyun ortama ısı vererek sıcaklığın çok düşmesini önlemesi', ['Suyun buharlaşarak ortamı soğutması', 'Suyun meyvelerin şekerini çözmesi', 'Suyun havadaki oksijeni tutması'], 'Su donarken her gram için yaklaşık 334 J ısı açığa çıkarır. Bu ısı, ortamın sıcaklığının 0 °C\'nin çok altına inmesini geciktirir.'),
  ('Sıfırın altındaki dondurucudan çıkarılan buz kalıbına dokunan ıslak parmağın buza yapışması nasıl açıklanır?', 'Parmaktaki ince su tabakasının ısısını buza verip donması', ['Buzun parmaktan su emmesi', 'Buzun parmağı ısıtması', 'Buzun bir anda süblimleşmesi'], 'Çok soğuk buz, parmaktaki ince su tabakasından ısı çeker; su donarak parmak ile buz arasında köprü kurar.'),
  ('Saf bir maddenin donma noktasında sıvıdan ısı çekilmeye devam edildikçe hangisi gerçekleşir?', 'Sıcaklık sabit kalırken katı miktarı artar', ['Sıcaklık düşerken sıvı miktarı artar', 'Sıcaklık yükselir', 'Sıcaklık düşerken sıvı ve katı miktarı sabit kalır'], 'Donma noktasında çekilen ısı, sıvının katıya dönüşmesiyle açığa çıkan ısıyla karşılanır; tüm sıvı donana kadar sıcaklık sabit kalır.'),
  ('Katı iyotun bir beherde hafifçe ısıtılıp üzerine soğuk bir cam konduğunda, camın altında mor kristallerin toplandığı görülür. Bu deneyde sırasıyla hangi hâl değişimleri gerçekleşir?', 'Süblimleşme, ardından kırağılaşma', ['Erime, ardından donma', 'Buharlaşma, ardından yoğuşma', 'Erime, ardından kaynama ve yoğuşma'], 'İyot katıdan doğrudan mor buhara geçer; buhar soğuk cama değince yeniden doğrudan katı kristallere dönüşür.'),
  ('Dondurucuda uzun süre açıkta kalan buz küplerinin erimeden küçülmesinin nedeni nedir?', 'Buzun süblimleşmesi', ['Buzun dondurucuda erimesi', 'Buzun kırağılaşması', 'Buzun kaynaması'], 'Sıcaklık 0 °C\'nin altında olsa da buzun küçük bir buhar basıncı vardır; dondurucudaki kuru hava nedeniyle buz yavaş yavaş süblimleşir.'),
  ('Aynı ısıtıcıyla ısıtılan suyun ısınma eğrisinde kaynama bölümünün erime bölümünden çok daha uzun sürmesinin nedeni nedir?', 'Buharlaşma ısısının erime ısısından büyük olması', ['Kaynama noktasının erime noktasından yüksek olması', 'Su buharının buzdan daha yoğun olması', 'Kaynama sırasında ısıtıcının gücünün azalması'], 'Isı sabit hızla verildiğinde hâl değişiminin süresi gereken ısıyla orantılıdır. Suyun buharlaşma ısısı erime ısısının yaklaşık 6,8 katıdır.'),
  ('Suyun özgül ısısı 4,18 J/(g·°C)\'dir. 200 g suyu 20 °C\'den 70 °C\'ye ısıtmak için kaç kJ ısı gerekir?', '41,8', ['20,9', '83,6', '4,180'], 'Q = m · c · ΔT = 200 · 4,18 · 50 = 41 800 J = 41,8 kJ.'),
  ('Bir karışım sabit hızla ısıtıldığında erime sırasında sıcaklığın sabit kalmayıp yavaşça yükseldiği görülüyor. Bu gözlemden ne sonuç çıkarılır?', 'Madde saf değildir', ['Madde kesinlikle bir elementtir', 'Madde amorf değil, kristal yapılı ve saftır', 'Isıtıcı arızalıdır'], 'Saf maddeler belirli bir sıcaklıkta erir. Karışımlarda erime boyunca bileşim değiştiği için erime bir sıcaklık aralığında gerçekleşir.'),
  ('Isıtılan bir maddenin hâl değişimi sırasında hangi büyüklük artar?', 'Potansiyel enerjisi', ['Ortalama kinetik enerjisi', 'Sıcaklığı', 'Kütlesi'], 'Hâl değişiminde sıcaklık, dolayısıyla ortalama kinetik enerji sabittir. Verilen enerji tanecikleri birbirinden uzaklaştırarak potansiyel enerjiyi artırır.'),
  ('Kritik sıcaklığın üzerindeki bir gaz için hangisi doğrudur?', 'Ne kadar basınç uygulanırsa uygulansın sıvılaştırılamaz', ['Basınç artırılınca hemen donar', 'Kendiliğinden sıvıya dönüşür', 'Hiç basınç uygulamaz'], 'Kritik sıcaklığın üzerinde taneciklerin kinetik enerjisi çok yüksektir; yalnız basınç artırarak sıvı faz oluşturulamaz, madde süperkritik akışkan olur.'),
  ('Faz diyagramındaki bir denge çizgisinin üzerinde bulunan bir nokta neyi ifade eder?', 'İki fazın dengede bir arada bulunduğu koşulu', ['Maddenin yalnız katı olduğu koşulu', 'Maddenin kimyasal olarak bozunduğu koşulu', 'Üç fazın birlikte dengede bulunduğu tek koşulu'], 'Denge çizgileri, çizginin iki yanındaki fazların birlikte dengede bulunabildiği sıcaklık ve basınç çiftlerini gösterir.'),
  ('Bir maddenin faz diyagramında sıvı-gaz denge eğrisi hangi noktada sona erer?', 'Kritik noktada', ['Üçlü noktada', 'Mutlak sıfırda', 'Normal erime noktasında'], 'Sıvı-gaz eğrisi üçlü noktada başlar ve kritik noktada biter; kritik noktanın ötesinde sıvı ile gaz fazı birbirinden ayırt edilemez.'),
  ('Faz diyagramında sabit sıcaklıkta basınç artırıldığında gaz fazından sıvı fazına geçen bir madde için hangi koşul gereklidir?', 'Sıcaklığın kritik sıcaklıktan düşük olması', ['Sıcaklığın kritik sıcaklıktan yüksek olması', 'Basıncın sıfıra inmesi', 'Maddenin amorf olması'], 'Gazlar yalnız kritik sıcaklıklarının altında sıkıştırılarak sıvılaştırılabilir; bu yüzden bazı gazlar önce soğutulmak zorundadır.'),
  ('Üçlü nokta basıncının altında sabit basınçta ısıtılan bir katı ne yapar?', 'Doğrudan gaza dönüşür', ['Önce erir sonra kaynar', 'Hiç hâl değiştirmez', 'Önce sıvılaşır sonra donar'], 'Üçlü nokta basıncının altında sıvı faz bölgesi bulunmadığından katı, ısıtıldığında doğrudan gaz fazına geçer, yani süblimleşir.'),
  ('Aynı sıcaklıktaki He ve CO₂ gazları için hangisi doğrudur?', 'Ortalama kinetik enerjileri eşittir', ['CO₂ tanecikleri daha hızlı hareket eder', 'He taneciklerinin kinetik enerjisi daha büyüktür', 'İki gazın ortalama hızları eşittir'], 'Ortalama kinetik enerji yalnız sıcaklığa bağlıdır. Enerjiler eşit olduğu için hafif olan He tanecikleri ortalamada daha hızlıdır.'),
  ('Bir gaz örneğinin mutlak sıcaklığı 300 K\'den 600 K\'ye çıkarıldığında taneciklerin ortalama kinetik enerjisi nasıl değişir?', 'İki katına çıkar', ['Dört katına çıkar', 'Yarıya iner', 'Karekökü kadar artarak yaklaşık 1,41 katına çıkar'], 'Ortalama kinetik enerji mutlak sıcaklıkla doğru orantılıdır; sıcaklık iki katına çıkınca enerji de iki katına çıkar. Hız ise yaklaşık 1,41 katına çıkar.'),
  ('Barometrelerde su yerine cıva kullanılmasının temel nedeni nedir?', 'Cıvanın yoğunluğunun çok yüksek olması', ['Cıvanın renksiz olması', 'Cıvanın kolay buharlaşması', 'Cıvanın suda kolayca çözünerek karışması'], 'Cıva sudan yaklaşık 13,6 kat yoğundur. Su kullanılsaydı açık hava basıncını dengelemek için yaklaşık 10 m uzunluğunda bir boru gerekirdi.'),
  ('1 atm basınç kaç pascal (Pa) değerine eşittir?', '101 325', ['1 000', '76 000', '10 132 500'], 'Standart atmosfer basıncı tanım gereği 101 325 Pa, yani yaklaşık 101,3 kPa\'dır.'),
  ('Bir dalgıcın 10 m derinlikte (toplam basınç yaklaşık 2 atm) ağzından çıkan 1 L hacimli hava kabarcığı, sıcaklık değişmezse yüzeye (1 atm) ulaştığında yaklaşık kaç L olur?', '2', ['0,5', '1', '4'], 'P₁V₁ = P₂V₂: 2 · 1 = 1 · V₂, V₂ = 2 L. Yükselen kabarcık, üzerindeki basınç azaldıkça genleşir.'),
  ('Uçakta kalkış sonrası yolcunun cebindeki kapalı cips paketinin şişmesi en iyi hangi ilkeyle açıklanır?', 'Dış basınç azalınca paketteki gazın genleşmesi', ['Paketteki gazın kimyasal tepkimeye girmesi', 'Kabin sıcaklığının çok yükselmesi', 'Paketin dışarıdan sürekli hava alması'], 'Kabin basıncı yer seviyesinden düşük tutulur. Paketteki gaz miktarı ve sıcaklığı sabitken dış basınç düşünce gazın hacmi artar.'),
  ('Pistonlu bir kapta 1 atm\'de 10 L gaz vardır. Sıcaklık sabit tutularak piston hacmi 2,5 L olacak şekilde itiliyor. Gazın son basıncı kaç atm olur?', '4', ['2,5', '0,25', '40'], 'P₂ = P₁V₁ / V₂ = 1 · 10 / 2,5 = 4 atm.'),
  ('Sabit sıcaklıkta bir gazın basıncı artarken yoğunluğu nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Önce artar sonra azalır'], 'Kütle sabit, hacim basınçla ters orantılı olarak azaldığından yoğunluk (kütle/hacim) basınçla doğru orantılı olarak artar.'),
  ('Sabit basınçta 27 °C\'de 3 L hacim kaplayan bir gaz 127 °C\'ye ısıtılırsa hacmi kaç L olur?', '4', ['2,25', '14,1', '6'], 'Sıcaklıklar Kelvin\'e çevrilir: 300 K ve 400 K. V₂ = 3 · 400 / 300 = 4 L.'),
  ('Bir öğrenci sabit basınçta 10 °C\'deki gazı 20 °C\'ye ısıtınca hacminin iki katına çıkacağını iddia ediyor. Bu iddianın hatası nedir?', 'Celsius sıcaklıkla oran kurulmuştur', ['Gaz hacmi sıcaklıkla azalır', 'Basınç sabitken hacim değişmez', 'Gaz hacmi yalnız miktara bağlıdır'], 'Charles yasası mutlak sıcaklıkla geçerlidir. 283 K\'den 293 K\'ye çıkışta hacim yalnız yaklaşık %3,5 artar.'),
  ('Charles yasasına göre sabit basınçta ideal bir gazın hacmi hangi sıcaklıkta kuramsal olarak sıfıra ulaşır?', '–273 °C', ['0 °C', '–100 °C', '–373 °C'], 'Hacim-sıcaklık doğrusunun sıcaklık eksenini kestiği nokta yaklaşık –273,15 °C\'dir; bu değer mutlak sıfır olarak kabul edilir.'),
  ('Sıcak hava balonlarının yükselmesi hangi ilkeye dayanır?', 'Isınan havanın genleşip yoğunluğunun azalması', ['Isınan havanın kütlesinin artması', 'Sıcak havanın basıncının sıfıra inmesi', 'Balon kumaşının havadan hafif olması'], 'Sabit basınçta ısıtılan hava genleşir; bir kısmı balondan taşar ve içerideki hava dış havadan daha az yoğun olur. Bu fark kaldırma kuvveti sağlar.'),
  ('Sabit hacimli çelik bir tüpte 27 °C\'de 3 atm basınçta gaz vardır. Tüp 227 °C\'ye ısıtılırsa basınç kaç atm olur?', '5', ['25,2', '1,8', '6'], 'T₁ = 300 K, T₂ = 500 K. P₂ = 3 · 500 / 300 = 5 atm.'),
  ('Uzun bir yolculuktan sonra ölçülen otomobil lastik basıncının, yola çıkmadan önceki değerden yüksek çıkmasının nedeni nedir?', 'Lastik içindeki havanın ısınması', ['Lastiğe dışarıdan hava girmesi', 'Lastik hacminin çok büyümesi', 'Lastikteki havanın sıvılaşması'], 'Yolda sürtünmeyle ısınan lastikteki havanın hacmi neredeyse sabittir; bu yüzden sıcaklık artışı basıncı yükseltir.'),
  ('Sabit hacimde bir gazın basıncı 2 atm\'den 1,5 atm\'ye düşmüştür. İlk sıcaklık 400 K ise son sıcaklık kaç K\'dir?', '300', ['533,3', '200', '267'], 'T₂ = T₁ · P₂ / P₁ = 400 · 1,5 / 2 = 300 K.'),
  ('Sabit hacimde gaz ısıtıldığında basıncın artmasının kinetik teoriye göre açıklaması nedir?', 'Tanecikler daha hızlı ve sık çarpar', ['Tanecik sayısı artar', 'Tanecikler büyür', 'Tanecikler birbirini çekmeye başlar'], 'Sıcaklık artınca taneciklerin hızı artar; çeperlere hem daha sık hem daha şiddetli çarparlar ve basınç yükselir.'),
  ('Sabit sıcaklık ve basınçta bir balonda 2 mol gaz 48 L hacim kaplıyor. Balona 1 mol daha aynı gazdan eklenirse hacim kaç L olur?', '72', ['24', '96', '36,5'], 'Sabit T ve P\'de hacim mol sayısıyla doğru orantılıdır: V₂ = 48 · 3 / 2 = 72 L.'),
  ('Aynı sıcaklık ve basınçta 1 L azot gazı ile 1 L helyum gazı karşılaştırıldığında hangisi farklıdır?', 'Kütleleri', ['Mol sayıları', 'Molekül sayıları', 'Hacimleri'], 'Avogadro yasasına göre mol ve tanecik sayıları eşittir; ancak N₂\'nin mol kütlesi (28 g/mol) He\'den (4 g/mol) büyük olduğundan kütleleri farklıdır.'),
  ('27 °C\'de 8,2 L hacimli bir kapta 0,5 mol ideal gaz bulunmaktadır. Gazın basıncı kaç atm\'dir? (R = 0,082 L·atm/(mol·K))', '1,5', ['0,75', '3,0', '1,35'], 'P = nRT / V = 0,5 · 0,082 · 300 / 8,2 = 1,5 atm.'),
  ('127 °C ve 2 atm koşullarında 16,4 L hacim kaplayan ideal gaz kaç moldür? (R = 0,082 L·atm/(mol·K))', '1', ['0,5', '2', '6,4'], 'n = PV / RT = 2 · 16,4 / (0,082 · 400) = 32,8 / 32,8 = 1 mol.'),
  ('Birleşik gaz yasası P₁V₁/T₁ = P₂V₂/T₂ hangi koşulda doğrudan kullanılabilir?', 'Gaz miktarı sabitken', ['Sıcaklık sabitken', 'Gaz bir karışım değilken', 'Basınç 1 atm\'yi geçmezken'], 'Birleşik gaz yasası Boyle, Charles ve Gay-Lussac yasalarını birleştirir; mol sayısı değişmediği sürece P, V ve T birlikte değişebilir.'),
  ('İdeal gaz denkleminde sıcaklık neden mutlaka Kelvin cinsinden yazılmalıdır?', 'Gaz yasaları mutlak sıcaklıkla orantı kurar', ['Celsius ölçeği negatif değer almaz', 'Kelvin daha küçük sayılar verir', 'R sabiti Celsius ile tanımsızdır ama Fahrenheit ile kullanılabilir'], 'Basınç ve hacim, sıfırı mutlak sıfır olan sıcaklıkla orantılıdır. Celsius kullanılırsa 0 °C\'de hacim sıfır çıkmak gibi anlamsız sonuçlar doğar.'),
  ('Kapalı, sabit hacimli bir kaba aynı sıcaklıkta biraz daha gaz pompalanırsa basınç artar. Bunun kinetik teoriye göre nedeni nedir?', 'Birim zamanda çarpışma sayısının artması', ['Taneciklerin hızının azalması', 'Taneciklerin daha büyük hâle gelmesi', 'Kabın sıcaklığının kendiliğinden düşmesi'], 'Aynı sıcaklıkta taneciklerin hızı değişmez; ancak tanecik sayısı arttığı için çeperlere birim zamanda daha çok çarpışma olur.'),
  ('Gaz yoğunluğunu veren ifade hangisidir? (M: mol kütlesi)', 'd = PM / RT', ['d = RT / PM', 'd = PV / nR', 'd = nM / P'], 'PV = (m/M)RT ifadesi düzenlenirse m/V = PM/RT bulunur. Yoğunluk basınç ve mol kütlesiyle doğru, sıcaklıkla ters orantılıdır.'),
  ('Normal koşullarda yoğunluğu 1,25 g/L olan bir gazın mol kütlesi kaç g/mol\'dür?', '28', ['22,4', '56', '17,9'], 'M = d · 22,4 = 1,25 · 22,4 = 28 g/mol. Bu değer N₂ ya da CO gazına uyar.'),
  ('Karbon dioksit (44 g/mol) yangın söndürmede alevi örterek etkili olur. Bu kullanımda CO₂\'nin hangi özelliği işe yarar?', 'Havadan daha yoğun olması', ['Havadan daha hafif olması', 'Yanıcı olması', 'Suda hiç çözünmemesi'], 'CO₂ havadan yaklaşık 1,5 kat yoğundur; alevin üzerine çökerek yanma bölgesine oksijen ulaşmasını engeller.'),
  ('Kapalı bir kaptaki 5,6 g ideal gaz, normal koşullarda 4,48 L hacim kaplıyor. Gazın mol kütlesi kaç g/mol\'dür?', '28', ['25', '1,25', '56'], 'n = 4,48 / 22,4 = 0,2 mol; M = 5,6 / 0,2 = 28 g/mol.'),
  ('Aynı sıcaklık ve basınçta X gazının yoğunluğu O₂ gazının (32 g/mol) yoğunluğunun 2 katıdır. X\'in mol kütlesi kaç g/mol\'dür?', '64', ['16', '32', '128'], 'Aynı koşullarda yoğunluk oranı mol kütlesi oranına eşittir: M_X = 2 · 32 = 64 g/mol (örneğin SO₂).'),
  ('Aynı sıcaklık ve basınçta eşit kütlelerde alınan H₂ (2 g/mol) ve CH₄ (16 g/mol) gazlarından H₂\'nin hacmi CH₄\'ün hacminin kaç katıdır?', '8', ['1/8', '4', '16'], 'Eşit kütlede mol sayısı mol kütlesiyle ters orantılıdır: n(H₂)/n(CH₄) = 16/2 = 8. Aynı koşullarda hacim oranı mol oranına eşittir.'),
  ('Bir kapta 0,2 mol N₂ ve 0,3 mol O₂ bulunmaktadır. Toplam basınç 5 atm ise O₂\'nin kısmi basıncı kaç atm\'dir?', '3', ['2', '1,5', '2,5'], 'O₂\'nin mol kesri 0,3 / 0,5 = 0,6\'dır. Kısmi basınç = 0,6 · 5 = 3 atm.'),
  ('Kuru havanın hacimce yaklaşık %21\'i oksijendir. Deniz seviyesinde (1 atm) havadaki oksijenin kısmi basıncı yaklaşık kaç atm\'dir?', '0,21', ['0,79', '1', '0,021'], 'Gaz karışımlarında hacim yüzdesi mol yüzdesine eşittir; kısmi basınç = 0,21 · 1 atm = 0,21 atm.'),
  ('Sabit hacimli ve sabit sıcaklıktaki bir kapta bulunan He gazına bir miktar Ar gazı eklenirse He\'nin kısmi basıncı nasıl değişir?', 'Değişmez', ['Artar', 'Azalır', 'Sıfıra iner'], 'He\'nin kısmi basıncı yalnız kendi mol sayısına, hacme ve sıcaklığa bağlıdır. Ar eklenmesi toplam basıncı artırır ama He\'nin basıncını değiştirmez.'),
  ('Yükseklere tırmanan dağcıların ek oksijen kullanmasının nedeni nedir?', 'Oksijenin kısmi basıncının azalması', ['Havadaki oksijen yüzdesinin sıfıra inmesi', 'Havanın tamamen karbon dioksite dönüşmesi', 'Sıcaklık düşünce oksijenin sıvılaşması'], 'Havanın bileşimi yüksekte de yaklaşık aynıdır; ancak toplam basınç düştüğü için oksijenin kısmi basıncı ve solunumla alınan oksijen miktarı azalır.'),
  ('25 °C\'de su üzerinde toplanan oksijenin toplam basıncı 750 mmHg\'dir. Suyun bu sıcaklıktaki buhar basıncı 24 mmHg ise kuru oksijenin kısmi basıncı kaç mmHg\'dir?', '726', ['774', '750', '702'], 'P(O₂) = P(toplam) – P(su buharı) = 750 – 24 = 726 mmHg.'),
  ('Su üzerinde gaz toplama yönteminin hangi gazlar için uygun olmadığı söylenir?', 'Suda çok çözünen gazlar', ['Suda az çözünen gazlar', 'Renksiz gazlar', 'Havadan hafif olan bütün gazlar'], 'Amonyak ya da hidrojen klorür gibi suda çok çözünen gazlar, toplanırken suya geçtiği için bu yöntemle toplanamaz.'),
  ('Su üzerinde toplanan bir gazın kısmi basıncı hesaplanırken suyun buhar basıncı değeri neye göre seçilir?', 'Suyun sıcaklığına', ['Toplanan gazın türüne', 'Kabın hacmine', 'Toplanan gazın kütlesine'], 'Suyun buhar basıncı yalnız sıcaklığa bağlıdır; bu nedenle deneyin yapıldığı sıcaklıktaki değer tablodan alınır.'),
  ('Uzun bir cam borunun bir ucuna derişik HCl, diğer ucuna derişik NH₃ çözeltisine batırılmış pamuklar aynı anda konuyor. Beyaz NH₄Cl halkası nerede oluşur?', 'HCl ucuna daha yakın', ['NH₃ ucuna daha yakın', 'Borunun tam ortasında', 'Halka oluşmaz'], 'NH₃ (17 g/mol) HCl\'den (36,5 g/mol) daha hafiftir ve daha hızlı yayılır; gazlar HCl ucuna daha yakın bir noktada buluşur.'),
  ('Aynı koşullarda He\'nin (4 g/mol) yayılma hızı, CH₄\'ün (16 g/mol) yayılma hızının kaç katıdır?', '2', ['4', '1/2', '16'], 'r(He)/r(CH₄) = √(16/4) = √4 = 2.'),
  ('Bir gazın küçük bir delikten vakuma kaçmasına ne ad verilir?', 'Efüzyon', ['Difüzyon', 'Osmoz', 'Sedimantasyon'], 'Efüzyon, gaz taneciklerinin küçük bir delikten boş bir bölgeye kaçmasıdır; difüzyon ise bir gazın başka bir gaz içinde yayılmasıdır. İkisi de Graham yasasına uyar.'),
  ('Helyumla şişirilmiş lastik bir balonun, aynı büyüklükteki hava dolu balondan daha çabuk sönmesinin nedeni nedir?', 'Helyum atomlarının daha hızlı efüzyona uğraması', ['Helyumun lastikle tepkimeye girmesi', 'Helyumun havadan ağır olması', 'Helyumun balon içinde sıvılaşarak hacminin küçülmesi'], 'Helyum havadan çok hafiftir; lastikteki mikroskobik gözeneklerden daha hızlı kaçar ve balon daha kısa sürede söner.'),
  ('Aynı koşullarda aşağıdaki gazlardan hangisinin ideal davranıştan sapması en azdır?', 'Helyum', ['Amonyak', 'Su buharı', 'Kükürt dioksit'], 'Helyum atomları küçük ve apolardır; aralarındaki çekim çok zayıftır. Polar ve hidrojen bağı yapabilen NH₃ ile H₂O ideal davranıştan çok sapar.'),
  ('Bir gazı sıvılaştırmanın en etkili yolu hangisidir?', 'Kritik sıcaklığın altına soğutup sıkıştırmak', ['Kritik sıcaklığın üzerine ısıtıp sıkıştırmak', 'Basıncı düşürüp ısıtmak', 'Sabit sıcaklıkta hacmini olabildiğince büyütmek'], 'Sıvılaşma için tanecikler birbirine yaklaştırılmalı ve enerjileri azaltılmalıdır; bu da kritik sıcaklığın altında soğutma ve sıkıştırmayla sağlanır.'),
  ('Sıkıştırılmış bir gazın dar bir açıklıktan düşük basınçlı bölgeye genleştirilmesiyle soğuması olayına ne ad verilir?', 'Joule-Thomson olayı', ['Tyndall olayı', 'Osmoz olayı', 'Brown hareketi olayı'], 'Genleşen gazın tanecikleri birbirinden uzaklaşırken çekim kuvvetlerine karşı iş yapar ve kinetik enerjileri azalır. Buzdolapları ve havanın sıvılaştırılması bu ilkeden yararlanır.'),
  ('Plazmayı sıradan bir gazdan ayıran temel özellik nedir?', 'Elektriği iletmesi', ['Belirli bir hacminin olması', 'Tanecikleri arasında hiç boşluk olmaması', 'Düzenli bir kristal örgü oluşturması'], 'Plazmadaki serbest elektronlar ve iyonlar elektrik akımını iletir ve manyetik alandan etkilenir; nötr gazlar normal koşullarda iletken değildir.'),
  ('Neon reklam lambalarında ve şimşekte görülen ışıma hangi madde hâliyle ilgilidir?', 'Plazma', ['Katı', 'Sıvı', 'Kristal'], 'Elektrik boşalmasıyla gaz iyonlaşır ve plazma oluşur; uyarılmış taneciklerin ışıması renkli ışığın kaynağıdır.'),
  ('Bir maddenin saf olduğunu en güvenilir biçimde gösteren gözlem hangisidir?', 'Sabit basınçta belirli bir sıcaklıkta erimesi', ['Renksiz olması', 'Suda çözünmesi', 'Kokusunun olmaması ve renksiz görünmesi'], 'Saf maddelerin erime ve kaynama noktaları sabit ve belirlidir; karışımlar ise bir sıcaklık aralığında hâl değiştirir. Renk, koku ve çözünme saflık ölçütü değildir.'),
  ('Karışımları bileşiklerden ayıran özellik hangisidir?', 'Bileşenlerin oranı değişebilir', ['Bileşenler kimyasal bağlarla birbirine bağlıdır', 'Kesin bir formülle gösterilir', 'Fiziksel yollarla bileşenlerine ayrılamaz'], 'Karışımlarda bileşenler istenen oranda bir araya gelebilir ve özelliklerini korur. Bileşiklerde ise oran sabittir ve ayrılmaları kimyasal yöntem gerektirir.'),
  ('Demir tozu ile kükürt tozunun karıştırılmasıyla elde edilen karışımın, ısıtılarak elde edilen demir(II) sülfürden farkı nedir?', 'Karışımdaki demir mıknatısla ayrılabilir', ['Karışımda yeni bir madde oluşmuştur', 'Demir(II) sülfür bir karışımdır', 'Karışımdaki bileşenler belirli ve sabit oranda bulunur'], 'Karışımda demir özelliğini koruduğu için mıknatısla çekilir. Isıtma sonucu oluşan FeS ise yeni bir bileşiktir ve demir mıknatısla ayrılamaz.'),
  ('Şekerli suyun karışım olduğunu destekleyen kanıt hangisidir?', 'Su buharlaştırılınca şekerin geri kazanılması', ['Tadının tatlı olması', 'Saydam görünmesi', 'Oda sıcaklığında sıvı hâlde bulunması'], 'Buharlaştırma fiziksel bir işlemdir; şekerin değişmeden geri kazanılabilmesi bileşenlerin kimyasal olarak birleşmediğini gösterir.'),
  ('Bir çözeltinin homojen olduğunu gösteren gözlem hangisidir?', 'Hangi bölümünden örnek alınırsa alınsın derişimin aynı çıkması', ['Bekletilince dibe çökelti birikmesi', 'Işığın içinden geçerken yolunun görünmesi', 'Süzgeç kâğıdında katı tanecik kalması'], 'Homojen karışımın her bölümü aynı bileşimdedir. Çökelme, ışık saçılması ve süzgeçte kalma heterojen karışımların belirtileridir.'),
  ('Hangi karışımda bileşenler aynı fiziksel hâlde bulunmaz?', 'Gazoz', ['Etil alkol ile su', 'Altın ile gümüş alaşımı', 'Azot ile oksijen'], 'Gazozda gaz hâldeki CO₂ sıvı suda çözünmüştür; çözünen gaz, çözücü sıvıdır. Diğer seçeneklerde iki bileşen de aynı hâldedir.'),
  ('Koloidal karışımlarda dağılan taneciklerin boyutu yaklaşık hangi aralıktadır?', '1 nm ile 1000 nm arası', ['0,01 nm ile 0,1 nm arası', '1 mm ile 1 cm arası', '1 cm\'den büyük, gözle görülebilir boyutta'], 'Çözeltilerde tanecikler 1 nm\'den küçük, süspansiyonlarda yaklaşık 1000 nm\'den büyüktür. Koloidler bu ikisinin arasında kalır.'),
  ('Mayonez hangi tür koloide örnektir?', 'Emülsiyon', ['Aerosol', 'Köpük', 'Katı sol'], 'Mayonezde yağ damlacıkları yumurta sarısının yardımıyla su içinde dağılmıştır; birbirinde çözünmeyen iki sıvının karışımı emülsiyondur.'),
  ('Bir koloidi gerçek bir çözeltiden ayırt etmek için hangi basit deney kullanılabilir?', 'Karanlık ortamda içinden lazer ışığı geçirmek', ['Karışımı normal süzgeç kâğıdından süzmek', 'Karışımın rengini gözle incelemek', 'Karışımı bir gün boyunca kapalı kapta bekletmek'], 'Koloidal tanecikler ışığı saçtığından lazer ışınının yolu görünür; gerçek çözeltilerde ise ışın yolu görünmez. Koloidler süzgeç kâğıdından geçer ve kolay çökmez.'),
  ('Sis ve duman ortak hangi koloit türüne girer?', 'Aerosol', ['Emülsiyon', 'Jel', 'Köpük'], 'Aerosollerde dağılma ortamı gazdır. Siste sıvı damlacıklar, dumanda katı tanecikler havada dağılmıştır.'),
  ('Bir sabun köpüğü ya da çırpılmış krema hangi koloit türüne örnektir?', 'Köpük', ['Aerosol', 'Emülsiyon', 'Katı sol'], 'Köpükte gaz kabarcıkları bir sıvı ya da katı içinde dağılmıştır; çırpılmış kremada hava kabarcıkları sıvı yağ-su karışımına hapsolmuştur.'),
  ('Saf demir yerine çeliğin inşaat ve makinelerde tercih edilmesinin başlıca nedeni nedir?', 'Daha sert ve dayanıklı olması', ['Elektriği hiç iletmemesi', 'Suda kolayca çözünebilmesi', 'Demirden çok daha düşük sıcaklıkta kaynaması'], 'Demir örgüsüne giren az miktardaki karbon atomları katmanların kaymasını zorlaştırır; bu da çeliği saf demirden daha sert ve sağlam yapar.'),
  ('Paslanmaz çeliğin paslanmaya karşı dayanıklı olmasını sağlayan başlıca alaşım bileşeni hangisidir?', 'Krom', ['Kurşun', 'Kalay', 'Cıva'], 'Krom yüzeyde ince ve koruyucu bir krom oksit tabakası oluşturur; bu tabaka demirin oksijen ve nemle temasını engeller.'),
  ('Takılarda kullanılan 22 ayar altın için hangisi doğrudur?', 'Kütlece yaklaşık 22/24 oranında altın içeren bir alaşımdır', ['Tamamen saf altındır', 'Altın içermeyen, yalnız bakırdan oluşan bir metaldir', 'Altın ve oksijenden oluşan bir bileşiktir'], 'Ayar sistemi 24\'lük ölçeğe dayanır: 22 ayar altının kütlece yaklaşık %91,7\'si altındır, kalanı bakır ve gümüş gibi metallerdir.'),
  ('Diş dolgularında kullanılan amalgam hangi metalin başka metallerle oluşturduğu alaşımdır?', 'Cıva', ['Alüminyum', 'Demir', 'Magnezyum'], 'Cıvanın diğer metallerle (gümüş, kalay, bakır) oluşturduğu alaşımlara amalgam denir.'),
  ('Tuzlu suyu süzgeç kâğıdından geçiren bir öğrenci, süzüntünün hâlâ tuzlu olduğunu görüyor. Bunun nedeni nedir?', 'Çözünmüş iyonların süzgecin gözeneklerinden geçebilmesi', ['Süzgeç kâğıdının yırtık olması', 'Tuzun suyla tepkimeye girip yeni madde oluşturması', 'Süzgeç kâğıdının içinden kendiliğinden tuz açığa çıkarması'], 'Çözeltide tuz iyonlar hâlinde dağılmıştır ve bu tanecikler süzgeç gözeneklerinden çok küçüktür; homojen karışımlar süzme ile ayrılamaz.'),
  ('Çay demlendikten sonra yaprakların süzgeçle ayrılması ile kahve telvesinin dibe çökmesi beklenip kahvenin fincandan içilmesi sırasıyla hangi yöntemlere örnektir?', 'Süzme ve dekantasyon', ['Dekantasyon ve damıtma', 'Damıtma ve süzme', 'Kristallendirme ve süzme'], 'Çay süzgeci tanecik boyutu farkıyla ayırır (süzme). Telvenin çökmesini bekleyip üstteki sıvıyı almak ise dekantasyondur.'),
  ('Kaynama noktaları birbirine yakın olan sıvıları içeren bir karışımı ayırmak için hangi yöntem kullanılır?', 'Ayrımsal damıtma', ['Basit damıtma', 'Dekantasyon', 'Süzgeç kâğıdından süzme'], 'Ayrımsal damıtmada damıtma kolonu buharın tekrar tekrar yoğuşup buharlaşmasını sağlar; her basamakta uçucu bileşen zenginleşir.'),
  ('Sıvılaştırılmış havadan azot, oksijen ve argonun ayrı ayrı elde edilmesi hangi özellik farkından yararlanır?', 'Kaynama noktası', ['Manyetik özellik', 'Renk', 'Tanecik boyutu'], 'Sıvı hava yavaşça ısıtıldığında en düşük kaynama noktalı azot (–196 °C) önce, ardından argon (–186 °C) ve oksijen (–183 °C) buharlaşır.'),
  ('Kaynama noktası 78 °C olan bir alkol ile su (100 °C) karışımı ayrımsal damıtıldığında ilk toplanan sıvı hangi maddece zengin olur?', 'Kaynama noktası düşük olan bileşen', ['Su', 'İki bileşen eşit oranda', 'Çözünmüş tuzlar'], 'Kaynama noktası düşük olan etil alkolün buhar basıncı daha yüksektir; bu yüzden buhar ve ilk yoğuşan sıvı alkolce zengindir.'),
  ('Buharlaştırma ile damıtma arasındaki temel fark nedir?', 'Damıtmada çözücü de geri kazanılır', ['Buharlaştırmada çözücü ısıtılmaz', 'Damıtma yalnız katı karışımlar için kullanılır', 'Buharlaştırmada çözünen madde de uçup gider'], 'Buharlaştırmada yalnız çözünen katı elde edilir, çözücü havaya karışır. Damıtmada buhar yoğuşturulduğu için çözücü de toplanır.'),
  ('Şeker fabrikalarında pancardan elde edilen şerbetten şeker kristalleri hangi yöntemle elde edilir?', 'Derişikleştirip kristallendirme', ['Ayrımsal damıtma', 'Ayırma hunisiyle ayırma', 'Kromatografi'], 'Şerbetteki su büyük ölçüde buharlaştırılarak çözelti derişikleştirilir; doygunluğu aşan çözeltide şeker kristalleri oluşur ve santrifüjle ayrılır.'),
  ('Kristallendirme ile ilgili hangisi doğrudur?', 'Yavaş soğutma daha iri kristaller oluşturur', ['Hızlı soğutma her zaman daha saf kristaller verir', 'Kristallendirme yalnız gazlarda uygulanır', 'Kristallendirme sırasında kimyasal tepkime gerçekleşir'], 'Yavaş soğutmada tanecikler düzenli konumlarına yerleşmeye zaman bulur ve büyük, düzgün kristaller oluşur. Kristallendirme fiziksel bir işlemdir.'),
  ('Ayırma hunisine konan su ile CCl₄ (yoğunluğu yaklaşık 1,59 g/mL) karışımı ayrılırken musluktan önce hangi sıvı akar?', 'CCl₄', ['Su', 'İkisi aynı anda karışık olarak', 'İki sıvı tek faz oluşturduğu için ayrılamaz'], 'Karbon tetraklorür sudan yoğundur ve suyla karışmaz; alt katmanda toplanır ve musluk açıldığında önce o akar.'),
  ('İyotlu sudan iyotu ayırmak için suya, suyla karışmayan ve iyotu çok iyi çözen bir organik çözücü eklenip çalkalanıyor. Bu yönteme ne ad verilir?', 'Özütleme', ['Ayrımsal damıtma', 'Kristallendirme', 'Dekantasyon ile çöktürme'], 'Özütlemede bir madde, daha iyi çözündüğü ikinci bir çözücüye aktarılır. İyot apolar çözücüye geçer, sonra iki faz ayırma hunisiyle ayrılır.'),
  ('Çay demlemek, katı çay yapraklarındaki bazı maddelerin sıcak suya geçmesini sağlar. Bu işlem hangi ayırma ilkesine örnektir?', 'Katı-sıvı özütleme', ['Damıtma', 'Süblimleştirme', 'Mıknatısla ayırma ve eleme'], 'Sıcak su, yapraktaki kafein, renk ve aroma maddelerini çözerek katıdan ayırır; çözünmeyen yapraklar geride kalır.'),
  ('Kromatografide hareketli fazla birlikte en uzağa ilerleyen bileşen için ne söylenebilir?', 'Durgun faza en zayıf tutunur', ['Durgun faza en güçlü tutunur', 'Hareketli fazda hiç çözünmez', 'Mol kütlesi en büyük olan bileşendir'], 'Hareketli fazda iyi çözünüp durgun faza zayıf tutunan bileşen, çözücüyle birlikte daha hızlı ve uzağa taşınır.'),
  ('Kâğıt kromatografisinde bir bileşenin Rf değeri nasıl hesaplanır?', 'Bileşenin aldığı yol / çözücünün aldığı yol', ['Çözücünün aldığı yol / bileşenin aldığı yol', 'Bileşenin aldığı yol · çözücünün aldığı yol', 'Bileşenin kütlesi / çözücünün hacmi'], 'Rf, bileşen lekesinin başlangıç çizgisinden uzaklığının, çözücü cephesinin uzaklığına oranıdır; 0 ile 1 arasında bir değerdir.'),
  ('Kromatografinin adli tıp, gıda denetimi ve ilaç analizi gibi alanlarda yaygın kullanılmasının başlıca nedeni nedir?', 'Çok küçük miktarlardaki bileşenleri ayırabilmesi', ['Yalnız tek bir bileşenli maddeyle çalışabilmesi', 'Çözücü gerektirmemesi', 'Yalnız metalleri ayırabilmesi'], 'Kromatografi, birbirine çok benzeyen ve çok az miktarda bulunan bileşenleri bile ayırıp tanımlamaya olanak verir.'),
  ('Harmanda buğday tanelerinin rüzgârda savrularak samandan ayrılması hangi ilkeye dayanır?', 'Tanecik kütle ve yoğunluk farkı', ['Kaynama noktası farkı', 'Çözünürlük farkı', 'Taneciklerin manyetik özellik farkı'], 'Hafif saman parçaları rüzgârla uzağa taşınırken daha ağır buğday taneleri yakına düşer.'),
  ('Yemeklik yağ lekesinin suyla çıkmayıp benzin ya da tiner gibi bir çözücüyle çıkmasının nedeni nedir?', 'Yağ ile bu çözücülerin apolar olması', ['Yağın suyla tepkimeye girmesi', 'Benzinin yağı kimyasal olarak parçalaması', 'Yağın sudan çok daha yoğun olması'], 'Apolar yağ molekülleri apolar çözücü molekülleriyle London kuvvetleri üzerinden etkileşir ve onlarda çözünür; polar su ile bu etkileşim zayıftır.'),
  ('Sofra tuzu suda çözünürken Na⁺ ve Cl⁻ iyonlarının su molekülleri tarafından sarılmasına ne ad verilir?', 'Hidratasyon', ['Süblimleşme', 'Kristallenme', 'Polimerleşme'], 'Su molekülleri, kısmi negatif oksijen uçlarıyla Na⁺ iyonlarını, kısmi pozitif hidrojen uçlarıyla Cl⁻ iyonlarını sarar; bu olaya hidratasyon (sulu ortamda solvatasyon) denir.'),
  ('İyot (I₂) katısının suda çok az, karbon tetraklorürde ise iyi çözünmesi nasıl açıklanır?', 'I₂ ve CCl₄ apolar, su ise polardır', ['I₂ polar, CCl₄ apolardır', 'Su iyotla tepkimeye girer', 'CCl₄ iyonik bir sıvıdır ve iyotla tuz oluşturur'], 'Apolar I₂ molekülleri, apolar CCl₄ molekülleriyle benzer türde (London) etkileşim kurar. Polar su molekülleri arasındaki güçlü hidrojen bağları I₂ tarafından kolayca bozulamaz.'),
  ('Bir katının belirli sıcaklıktaki çözünürlüğünü değiştiren etken hangisidir?', 'Çözücünün türü', ['Katının toz hâline getirilmesi', 'Karışımın karıştırılması', 'Çözücü miktarının artırılması'], 'Çözünürlük madde ile çözücünün türüne, sıcaklığa (gazlarda ayrıca basınca) bağlıdır. Tanecik boyutu ve karıştırma yalnız çözünme hızını etkiler.'),
  ('Hazır sıcak kompreslerde kalsiyum klorürün suda çözünmesi kullanılır. Bu kullanım hangi özelliğe dayanır?', 'Çözünmesinin ekzotermik olmasına', ['Çözünmesinin endotermik olmasına', 'Suda hiç çözünmemesine', 'Suyun kaynama noktasını düşürmesine'], 'CaCl₂\'nin suda çözünmesi önemli miktarda ısı açığa çıkarır; poşetteki bölme kırılınca tuz çözünür ve kompres ısınır.'),
  ('Çözünmesi endotermik olan bir katının sudaki çözünürlüğü sıcaklık artınca genellikle nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Sıfıra iner'], 'Le Chatelier ilkesine göre ısı alan bir süreç, sıcaklık artışıyla ileri yönde kayar; bu yüzden endotermik çözünen katıların çözünürlüğü sıcaklıkla artar.'),
  ('Potasyum nitratın çözünürlüğü 20 °C\'de 32 g/100 g su, 60 °C\'de 110 g/100 g sudur. 60 °C\'de 100 g suyla hazırlanmış doymuş çözelti 20 °C\'ye soğutulursa kaç g KNO₃ çöker?', '78', ['32', '110', '142'], '60 °C\'de 110 g çözünmüşken 20 °C\'de yalnız 32 g çözünmüş kalabilir: 110 – 32 = 78 g katı çöker.'),
  ('Potasyum nitratın çözünürlüğü 40 °C\'de yaklaşık 64 g/100 g sudur. 40 °C\'de 200 g su ile hazırlanan doymuş çözelti kaç gramdır?', '328', ['264', '128', '164,0'], '200 g suda 2 · 64 = 128 g KNO₃ çözünür. Çözelti kütlesi = 200 + 128 = 328 g.'),
  ('Yaz aylarında sıcak göllerde balık ölümlerinin artmasının bir nedeni hangisidir?', 'Sıcaklık arttıkça sudaki oksijen çözünürlüğünün azalması', ['Sıcaklık arttıkça oksijen çözünürlüğünün artması', 'Suyun yoğunluğunun sıfıra inmesi', 'Sıcak suda oksijenin katılaşarak dibe çökmesi'], 'Gazların sudaki çözünürlüğü sıcaklık arttıkça azalır. Sıcak suda çözünmüş oksijen miktarı düşer ve canlılar için yetersiz kalabilir.'),
  ('Henry sabiti 1,3·10⁻³ mol/(L·atm) olan oksijenin, kısmi basıncı 0,2 atm iken sudaki çözünürlüğü kaç mol/L\'dir?', '2,6·10⁻⁴', ['6,5·10⁻³', '1,3·10⁻³', '2,6·10⁻³'], 'C = k · P = 1,3·10⁻³ · 0,2 = 2,6·10⁻⁴ mol/L.'),
  ('Bir çözeltiye küçük bir kristal parçası atıldığında hızla çok sayıda kristalin oluştuğu gözleniyor. Çözelti başlangıçta hangi durumdaydı?', 'Aşırı doymuş', ['Doymamış', 'Doymuş', 'Seyreltik ve doymamış'], 'Aşırı doymuş çözeltiler, çözünürlükten fazla çözünen içerir ve kararsızdır. Eklenen kristal çekirdek görevi yapar ve fazla çözünen hızla kristallenir.'),
  ('Doymuş bir şekerli su çözeltisine, sıcaklık sabitken bir miktar su eklenirse çözelti ne hâle gelir?', 'Doymamış', ['Aşırı doymuş', 'Doymuş kalır', 'Saf su'], 'Su eklenince çözünen miktarı aynı kalırken çözücü artar; çözelti çözünürlük sınırının altına iner ve doymamış hâle gelir.'),
  ('Kütlece %20\'lik 150 g çözeltiden 50 g su buharlaştırılırsa yeni derişim yüzde kaç olur?', '%30', ['%40', '%25', '%22,5'], 'Çözünen 150 · 0,20 = 30 g\'dır ve değişmez. Yeni çözelti 100 g olur: 30 / 100 · 100 = %30.'),
  ('Kütlece %40\'lık bir çözelti hazırlamak için 60 g suya kaç g çözünen eklenmelidir?', '40', ['24', '60', '66,7'], 'x / (x + 60) = 0,40 eşitliğinden x = 0,4x + 24, 0,6x = 24 ve x = 40 g bulunur.'),
  ('Hacimce %70\'lik etil alkol çözeltisinden 350 mL alkol içeren miktar kaç mL\'dir?', '500', ['245', '420', '437,5'], 'Çözelti hacmi = 350 · 100 / 70 = 500 mL.'),
  ('Hacimce yüzde derişim en çok hangi tür çözeltiler için kullanılır?', 'Sıvı-sıvı ve gaz-gaz çözeltileri', ['Katı-katı alaşımları', 'Yalnız katı tuz çözeltileri', 'Süspansiyonlar, emülsiyonlar ve köpükler'], 'Çözünen ve çözücünün hacimle ölçülmesinin kolay olduğu sıvı-sıvı (alkol-su) ve gaz-gaz (hava) karışımlarında hacimce yüzde kullanışlıdır.'),
  ('Bir içme suyu örneğinin 2 kg\'ında 0,6 mg florür iyonu bulunmaktadır. Florür derişimi kaç ppm\'dir?', '0,3', ['1,2', '3', '0,03'], '1 ppm, 1 kg çözeltide 1 mg çözüneni ifade eder. 0,6 mg / 2 kg = 0,3 mg/kg = 0,3 ppm.'),
  ('Bir gölün 500 kg suyunda 4 g nitrat bulunuyor. Nitrat derişimi kaç ppm\'dir?', '8', ['0,8', '80', '2'], '4 g / 500 000 g · 10⁶ = 8 ppm.'),
  ('11,7 g NaCl (58,5 g/mol) ile hazırlanan 500 mL çözeltinin molaritesi kaçtır?', '0,4 M', ['0,2 M', '0,8 M', '23,4 M'], 'n = 11,7 / 58,5 = 0,2 mol. M = 0,2 / 0,5 = 0,4 mol/L.'),
  ('0,5 M glikoz (180 g/mol) çözeltisinden 250 mL hazırlamak için kaç g glikoz gerekir?', '22,5', ['45', '90', '11,25'], 'n = 0,5 · 0,25 = 0,125 mol; kütle = 0,125 · 180 = 22,5 g.'),
  ('Hacmi 200 mL olan 0,3 M bir KCl çözeltisinde kaç mol K⁺ iyonu vardır?', '0,06', ['0,6', '1,5', '0,015'], 'n = M · V = 0,3 · 0,2 = 0,06 mol KCl; her KCl bir K⁺ verdiğinden 0,06 mol K⁺ vardır.'),
  ('0,2 M CaCl₂ çözeltisinde Cl⁻ iyonlarının derişimi kaç M\'dır?', '0,4', ['0,2', '0,1', '0,067'], 'Her CaCl₂ suda bir Ca²⁺ ve iki Cl⁻ iyonu verir; [Cl⁻] = 2 · 0,2 = 0,4 M.'),
  ('Laboratuvarda belirli molaritede çözelti hazırlarken hacmi kesin ölçmek için hangi cam malzeme kullanılır?', 'Balon joje', ['Beher', 'Erlenmayer', 'Saat camı ve damlalık'], 'Balon joje, boyun kısmındaki çizgiye kadar doldurulduğunda belirli bir hacmi yüksek doğrulukla verir; beher ve erlenmayer üzerindeki çizgiler yaklaşıktır.'),
  ('0,5 mol üre 250 g suda çözülüyor. Çözeltinin molalitesi kaçtır?', '2 m', ['0,5 m', '0,125 m', '1 m'], 'm = 0,5 mol / 0,25 kg = 2 mol/kg.'),
  ('Koligatif hesaplarda molarite yerine molalitenin tercih edilmesinin nedeni nedir?', 'Sıcaklıkla değişmemesi', ['Hesaplamasının daha uzun olması', 'Yalnız gazlar için tanımlı olması', 'Çözücü türünden bağımsız olması'], 'Molalite kütleler üzerinden tanımlanır; sıcaklık değişince hacim değişse de kütle değişmediği için molalite sabit kalır.'),
  ('6 M stok çözeltiden 0,5 M derişimli 300 mL çözelti hazırlamak için kaç mL stok çözelti alınmalıdır?', '25', ['36', '50', '3600'], 'V₁ = M₂V₂ / M₁ = 0,5 · 300 / 6 = 25 mL; bu hacim alınıp su ile 300 mL\'ye tamamlanır.'),
  ('Derişik sülfürik asit seyreltilirken neden asidin suya yavaş yavaş eklenmesi, suyun aside eklenmemesi gerekir?', 'Açığa çıkan büyük ısının sıçramaya yol açmaması için', ['Suyun asitle hiç karışmaması için', 'Asidin suda çözünmemesi için', 'Seyreltme ısı aldığı için kabın donup çatlamasını önlemek için'], 'Sülfürik asidin suyla karışması çok ekzotermiktir. Az suyun derişik asit üzerine eklenmesi suyu anında kaynatıp asidin sıçramasına neden olabilir.'),
  ('0,3 M 200 mL NaCl çözeltisi ile 0,6 M 100 mL NaCl çözeltisi karıştırılıyor. Karışımın derişimi kaç M\'dır?', '0,4', ['0,45', '0,9', '0,3'], 'Toplam mol: 0,3 · 0,2 + 0,6 · 0,1 = 0,06 + 0,06 = 0,12 mol. Toplam hacim 0,3 L: 0,12 / 0,3 = 0,4 M.'),
  ('0,4 M KNO₃ çözeltisinin 250 mL\'sindeki suyun bir kısmı buharlaştırılarak hacim 100 mL\'ye indiriliyor. Yeni derişim kaç M olur?', '1', ['0,16', '0,4', '2,5'], 'Çözünen mol sayısı 0,4 · 0,25 = 0,1 mol\'dür ve değişmez. 0,1 / 0,1 L = 1 M.'),
  ('Eşit derişimli NaCl, CaCl₂ ve glikoz çözeltilerinin elektrik iletkenliklerinin büyükten küçüğe sıralaması hangisidir?', 'CaCl₂ > NaCl > glikoz', ['NaCl > CaCl₂ > glikoz', 'Glikoz > NaCl > CaCl₂', 'NaCl = CaCl₂ > glikoz çözeltisi'], 'Aynı derişimde CaCl₂ üç, NaCl iki iyon verir; daha çok iyon daha yüksek iletkenlik sağlar. Glikoz iyonlaşmaz.'),
  ('Zayıf elektrolit ile kuvvetli elektrolit arasındaki fark nedir?', 'Zayıf elektrolit suda kısmen iyonlaşır', ['Zayıf elektrolit suda hiç çözünmez', 'Kuvvetli elektrolit yalnız gazdır', 'Zayıf elektrolit iyon yerine elektron üretir'], 'Kuvvetli elektrolitler suda neredeyse tamamen iyonlarına ayrışır; zayıf elektrolitlerde ise moleküllerin yalnız küçük bir kısmı iyonlaşır.'),
  ('Islak elle elektrikli aletlere dokunmanın tehlikeli olmasının kimyasal açıklaması nedir?', 'Deri üzerindeki suda çözünmüş iyonların akımı iletmesi', ['Saf suyun çok iyi bir iletken olması', 'Suyun elektrikle yanması', 'Suyun deride donarak yalıtkanlığı ortadan kaldırması'], 'Ter ve musluk suyunda çözünmüş tuzlar bulunur; bu iyonlar deri yüzeyinde iletken bir tabaka oluşturarak akımın vücuda geçmesini kolaylaştırır.'),
  ('Raoult yasasına göre uçucu olmayan çözünen içeren bir çözeltinin buhar basıncı nasıl hesaplanır?', 'Çözücünün mol kesri ile saf çözücünün buhar basıncının çarpımı', ['Çözünenin mol kesri ile saf çözücünün buhar basıncının çarpımı', 'Saf çözücünün buhar basıncının molaliteye bölümü', 'Çözünenin mol kesrinin saf çözücünün buhar basıncına bölümüyle bulunan değer'], 'P(çözelti) = X(çözücü) · P°(çözücü). Çözücünün mol kesri 1\'den küçük olduğundan buhar basıncı düşer.'),
  ('25 °C\'de saf suyun buhar basıncı 24 mmHg\'dir. Suyun mol kesrinin 0,9 olduğu bir şeker çözeltisinin buhar basıncı kaç mmHg olur?', '21,6', ['2,4', '26,4', '26,67'], 'P = X(su) · P° = 0,9 · 24 = 21,6 mmHg.'),
  ('Kaynama noktası yükselmesi bağıntısı ΔTk = Kk · m · i\'de \'i\' neyi gösterir?', 'Bir formül biriminin çözeltide verdiği tanecik sayısını', ['Çözücünün mol kütlesini', 'Çözeltinin hacmini', 'Çözünenin çözeltideki kütlece yüzde derişimini'], 'i (van\'t Hoff çarpanı), çözünenin bir biriminin çözeltide kaç tanecik oluşturduğunu gösterir: glikoz için 1, NaCl için yaklaşık 2, CaCl₂ için yaklaşık 3.'),
  ('Suyun kaynama noktası yükselme sabiti 0,52 °C/m\'dir. 1 atm\'de 2 m glikoz çözeltisi kaç °C\'de kaynar?', '101,04', ['100,52', '102', '100,104'], 'ΔTk = 0,52 · 2 · 1 = 1,04 °C; kaynama noktası 100 + 1,04 = 101,04 °C olur.'),
  ('Aynı molalitedeki NaCl ve glikoz çözeltilerinden NaCl çözeltisinin daha yüksek sıcaklıkta kaynamasının nedeni nedir?', 'NaCl\'nin iki iyona ayrışarak daha çok tanecik oluşturması', ['NaCl\'nin mol kütlesinin daha büyük olması', 'Glikozun suyla tepkimeye girmesi', 'NaCl\'nin suyla tepkimeye girerek çözeltide gaz oluşturması'], 'Koligatif özellikler tanecik sayısına bağlıdır. NaCl suda Na⁺ ve Cl⁻ iyonlarına ayrıştığı için aynı molalitede yaklaşık iki kat tanecik verir.'),
  ('Suyun donma noktası alçalma sabiti 1,86 °C/m\'dir. 0,5 m üre çözeltisi kaç °C\'de donar?', '–0,93', ['–1,86', '0,93', '–0,465'], 'ΔTd = 1,86 · 0,5 · 1 = 0,93 °C; donma noktası 0 – 0,93 = –0,93 °C olur.'),
  ('Eşit molalitedeki çözeltilerde donma noktası alçalması büyükten küçüğe nasıl sıralanır?', 'AlCl₃ > MgCl₂ > KCl > glikoz', ['Glikoz > KCl > MgCl₂ > AlCl₃', 'KCl > AlCl₃ > glikoz > MgCl₂', 'MgCl₂ > AlCl₃ > KCl > glikoz çözeltisi'], 'Tanecik sayıları: AlCl₃ 4, MgCl₂ 3, KCl 2, glikoz 1. Donma noktası alçalması tanecik sayısıyla orantılıdır.'),
  ('Kırmızı kan hücreleri çok tuzlu (hipertonik) bir çözeltiye konursa ne olur?', 'Su kaybederek büzüşürler', ['Su alarak şişip patlarlar', 'Hiçbir değişiklik olmaz', 'Tuzu tamamen dışarı atarlar'], 'Dıştaki çözelti daha derişik olduğundan su hücreden dışarı osmozla geçer ve hücre büzüşür. Saf suda ise su içeri girer ve hücre patlayabilir.'),
  ('Damar yoluyla verilen serum çözeltisinin kan ile izotonik olması neden gereklidir?', 'Kan hücrelerinin su alıp vermesini dengede tutmak için', ['Serumun daha hızlı akması için', 'Serumun renksiz görünmesi için', 'Kanın pıhtılaşmasını ve donmasını sağlamak için'], 'İzotonik çözeltinin ozmotik basıncı kanınkine eşittir; böylece hücreler ne su kaybedip büzüşür ne de fazla su alıp patlar. %0,9\'luk NaCl çözeltisi bunun örneğidir.'),
  ('Deniz suyundan içme suyu elde etmek için çözelti tarafına ozmotik basınçtan büyük basınç uygulanarak suyun zardan saf su tarafına geçirilmesine ne ad verilir?', 'Ters ozmoz', ['Ayrımsal damıtma', 'Süblimleştirme', 'Elektroforez'], 'Ters ozmozda dışarıdan uygulanan basınç doğal osmoz yönünü tersine çevirir; su molekülleri zardan geçer, tuz iyonları tutulur.'),
  ('Reçel ve salamura yapımında yüksek şeker ya da tuz derişiminin gıdayı bozulmaya karşı korumasının nedeni nedir?', 'Mikroorganizmaların osmozla su kaybetmesi', ['Şeker ve tuzun gıdayı dondurması', 'Gıdanın kaynama noktasının düşmesi', 'Mikroorganizmaların şeker ve tuzu hiç algılayamaması'], 'Derişik ortamda mikroorganizma hücrelerindeki su osmozla dışarı çıkar; susuz kalan hücreler çoğalamaz ve ölür.'),
  ('Suyun kaynama noktasının (100 °C), mol kütlesi benzer olan metanınkinden (–161 °C) çok yüksek olmasının nedeni nedir?', 'Su molekülleri arasındaki hidrojen bağları', ['Suyun iyonik bir bileşik olması', 'Su molekülünün metandan çok daha ağır olması', 'Metanın su gibi hidrojen bağı yapması'], 'Su molekülleri birbirine güçlü hidrojen bağlarıyla bağlanır; bu bağları koparmak çok enerji gerektirir. Apolar metanda yalnız zayıf London kuvvetleri vardır.'),
  ('Suyun özgül ısısının yüksek olmasının deniz kıyısındaki yerleşimlerin iklimine etkisi nedir?', 'Gece-gündüz sıcaklık farkının az olması', ['Kıyıların her zaman daha soğuk olması', 'Denizin gündüz hızla kaynaması', 'Kıyılarda yağışın hiç görülmemesi'], 'Su ısıyı yavaş alır ve yavaş verir; denizler gündüz ısı depolayıp gece yayar. Bu yüzden kıyı bölgelerinde sıcaklık farkları karalara göre küçüktür.'),
  ('Kışın soğuk dışarıdan sıcak ve nemli bir odaya giren birinin gözlük camlarının buğulanmasının nedeni nedir?', 'Soğuk camda odadaki su buharının yoğuşması', ['Sıcak havanın camı eritmesi', 'Camın içindeki suyun dışarı sızması', 'Odadaki havanın camla tepkimeye girmesi'], 'Soğuk gözlük camı, sıcak odanın nemli havasını çiy noktasının altına soğutur; su buharı cam yüzeyinde küçük damlacıklar hâlinde yoğuşur.'),
  ('Buzdolabı ve klimalarda soğutucu akışkan iç ünitede hangi olayla ortamdan ısı alır?', 'Buharlaşarak', ['Donarak', 'Yoğuşarak', 'Kristallenerek'], 'Soğutucu akışkan düşük basınçta buharlaşırken iç ortamdan ısı çeker; sıkıştırıldığı dış ünitede yoğuşurken bu ısıyı dışarı verir.'),
  ('Kışın çamaşırların dışarıda donduktan sonra yine de kuruyabilmesi hangi olayla açıklanır?', 'Buzun süblimleşmesi', ['Buzun kırağılaşması', 'Suyun kaynaması', 'Buzun yoğunlaşması'], 'Donmuş çamaşırdaki buz, kuru ve soğuk havada sıvılaşmadan doğrudan buhara dönüşür; böylece çamaşır yavaş yavaş kurur.'),
  ('Ayakkabı kutularına ve elektronik cihaz paketlerine konan küçük silika jel paketlerinin görevi nedir?', 'Ortamdaki nemi tutmak', ['Ortamı ısıtmak', 'Ürünü dondurmak', 'Ürüne hoş bir koku vermek ve küflenmeyi hızlandırmak'], 'Silika jel çok gözenekli bir katıdır ve büyük yüzey alanında su buharını tutar; böylece nemin ürüne zarar vermesi engellenir.'),
  ('Kaynamakta olan suya bir avuç soğuk makarna atıldığında kaynamanın kısa süre durmasının nedeni nedir?', 'Suyun sıcaklığının kaynama noktasının altına düşmesi', ['Makarnanın suyun kaynama noktasını sıfıra indirmesi', 'Makarnanın dış basıncı artırması', 'Suyun aniden donması'], 'Soğuk makarna sudan ısı alır; su sıcaklığı kaynama noktasının altına iner. Isıtma sürdükçe sıcaklık yeniden 100 °C\'ye çıkar ve kaynama başlar.'),
  ('Yüksek dağlarda yumurtanın deniz seviyesine göre daha geç pişmesinin nedeni nedir?', 'Suyun daha düşük sıcaklıkta kaynaması', ['Yumurtanın yüksekte büyümesi', 'Suyun daha yüksek sıcaklıkta kaynaması', 'Yüksekte ateşin hiç yanmaması'], 'Atmosfer basıncı düşük olduğundan su 100 °C\'nin altında kaynar; pişirme suyu daha soğuk kaldığı için proteinlerin pıhtılaşması daha uzun sürer.'),
  ('Gazlı içeceklerin buzdolabında saklandığında açıldıktan sonra daha uzun süre gazlı kalmasının nedeni nedir?', 'Düşük sıcaklıkta CO₂\'nin sudaki çözünürlüğünün daha yüksek olması', ['Soğukta CO₂\'nin suyla tepkimeye girip katılaşması', 'Buzdolabının şişedeki basıncı artırması', 'Soğukta suyun buharlaşmasının tümüyle durması'], 'Gazların sudaki çözünürlüğü sıcaklık düştükçe artar; soğuk içecekteki CO₂ daha yavaş kaçar.'),
  ('Kum, akabildiği ve bulunduğu kabın şeklini alabildiği hâlde neden sıvı sayılmaz?', 'Her kum tanesi belirli şekil ve hacme sahip bir katıdır', ['Kum taneleri gaz içerir', 'Kum tanelerinin hacmi yoktur', 'Kum, yalnız yüksek sıcaklıkta eriyerek akabilen bir sıvıdır'], 'Kumun akması, tek tek katı tanelerin birbiri üzerinden kaymasından kaynaklanır; tanelerin her biri katının belirli şekil ve hacim özelliklerini korur.'),
  ('Tereyağı ve çikolata gibi maddelerin belirli bir sıcaklıkta değil, yavaş yavaş yumuşayarak erimesinin bir nedeni nedir?', 'Farklı erime noktalı birçok bileşenden oluşmaları', ['Saf madde olmaları', 'Gaz hâlinde bulunmaları', 'Tamamen iyonik yapıda olup elektriği iletmeleri'], 'Tereyağı ve çikolata farklı yağ asitleri ve başka bileşenler içeren karışımlardır; bileşenler farklı sıcaklıklarda eridiği için erime bir aralıkta gerçekleşir.'),
  ('Su, gliserin ve bal aynı yükseklikten eğik bir düzleme aynı anda dökülüyor. Bu sıvıların düzlemin sonuna ulaşma sırası hangisidir?', 'Su, gliserin, bal', ['Bal, gliserin, su', 'Gliserin, su, bal', 'Bal, su, gliserin sırasıyla'], 'Viskozitesi en düşük olan su en hızlı akar. Gliserinin viskozitesi sudan çok büyüktür ama baldan küçüktür; en son bal ulaşır.'),
  ('Sıvı içinde serbestçe düşen bir bilyenin sabit hıza ulaşma süresinin ölçülmesiyle sıvının hangi özelliği belirlenebilir?', 'Viskozitesi', ['Buhar basıncı', 'Yüzey gerilimi', 'Erime noktası'], 'Bilyeli viskozimetrelerde bilyenin belirli bir mesafeyi düşme süresi sıvının iç sürtünmesine, yani viskozitesine bağlıdır.'),
  ('Bitkilerde suyun kökten yapraklara taşınmasına katkıda bulunan fiziksel etkenlerden biri hangisidir?', 'İnce iletim borularında kılcallık', ['Suyun köklerde kaynaması', 'Suyun yapraklarda donması', 'Toprağın basınç uygulayarak suyu yukarı itmesi'], 'Bitkilerdeki ince iletim boruları kılcal borular gibi davranır; su molekülleri ile boru çeperi arasındaki yapışma su sütununun yükselmesine katkı sağlar.'),
  ('25 °C\'de buhar basınçları A: 18 mmHg, B: 75 mmHg, C: 440 mmHg olan sıvılar için moleküller arası çekim kuvvetinin büyükten küçüğe sıralaması hangisidir?', 'A > B > C', ['C > B > A', 'B > A > C', 'B > C > A'], 'Buhar basıncı düşük olan sıvıda moleküller birbirini daha güçlü çeker ve sıvıdan daha zor kopar. Bu yüzden çekim kuvveti A\'da en büyük, C\'de en küçüktür.'),
  ('Ağzı açık bir kaptaki suyun, aynı sıcaklıkta geniş bir tepsideki eşit miktar sudan daha geç buharlaşmasının nedeni nedir?', 'Buharlaşma yüzeyinin daha küçük olması', ['Suyun buhar basıncının daha yüksek olması', 'Kabın suyu ısıtması', 'Tepsideki suyun daha yoğun olması'], 'Buharlaşma hızı yüzey alanıyla artar; geniş tepside daha çok molekül yüzeyde bulunduğundan su daha çabuk buharlaşır. Buhar basıncı ise yüzey alanına bağlı değildir.'),
  ('Bir sıvının kaynama noktası ile ilgili hangisi yanlıştır?', 'Sıvının miktarı arttıkça kaynama noktası yükselir', ['Dış basınç arttıkça kaynama noktası yükselir', 'Saf sıvılar için ayırt edici bir özelliktir', 'Uçucu olmayan bir çözünen eklenince kaynama noktası yükselir'], 'Kaynama noktası sıvının miktarına bağlı değildir; büyük miktar yalnız kaynamaya ulaşma süresini uzatır. Diğer ifadeler doğrudur.'),
  ('Suyun buharlaşma ısısı 2260 J/g\'dır. 100 °C\'deki 5 g su buharı aynı sıcaklıkta tamamen yoğuşurken ortama kaç J ısı verir?', '11 300', ['452', '2260', '1130,0'], 'Yoğuşma ısısı buharlaşma ısısına eşit büyüklüktedir: Q = 5 · 2260 = 11 300 J. Bu yüzden buhar yanıkları kaynar su yanıklarından daha ağırdır.'),
  ('100 °C\'deki su buharının, 100 °C\'deki kaynar sudan daha ağır yanıklara yol açmasının nedeni nedir?', 'Buharın deride yoğuşurken ek olarak büyük miktarda ısı vermesi', ['Buharın daha yüksek sıcaklıkta olması', 'Buharın deriyle kimyasal tepkimeye girmesi', 'Kaynar suyun deriye ısı vermemesi'], 'Buhar önce deride yoğuşarak gram başına yaklaşık 2260 J ısı verir, ardından oluşan sıcak su da soğurken ısı aktarır.'),
  ('Kırağılaşma için aşağıdakilerden hangisi doğrudur?', 'Isı veren bir süreçtir', ['Isı alan bir süreçtir', 'Katıdan gaza geçiştir', 'Yalnız çok yüksek sıcaklıklarda gerçekleşir'], 'Kırağılaşmada gaz tanecikleri doğrudan düzenli katı yapıya geçer; tanecikler arası etkileşimler kurulurken enerji ortama verilir.'),
  ('Saf bir sıvının sabit hızla soğutulmasını gösteren soğuma eğrisinde donma noktasında sıcaklığın sabit kalmasını sağlayan nedir?', 'Donma sırasında açığa çıkan ısının çekilen ısıyı karşılaması', ['Sıvının ısı almayı tamamen bırakması', 'Soğutucunun çalışmayı durdurması', 'Sıvının kütlesinin donma sırasında artması'], 'Sıvı donarken kristal yapı oluşurken ısı açığa çıkar; bu ısı soğutucunun çektiği ısıyı dengelediği için donma bitene kadar sıcaklık değişmez.'),
  ('Isınma eğrisinde katı fazın ısınmasını gösteren eğimli bölümde verilen ısı ne için harcanır?', 'Taneciklerin ortalama kinetik enerjisini artırmak için', ['Taneciklerin kimyasal bağlarını koparmak için', 'Katının kütlesini artırmak için', 'Taneciklerin tamamen gaz fazına geçip uzaklaşması için'], 'Tek fazlı bölgelerde verilen ısı tanecik hareketini hızlandırarak sıcaklığı yükseltir; hâl değişimi olmadığı için potansiyel enerji önemli ölçüde değişmez.'),
  ('Faz diyagramında sabit basınçta sıcaklık artırılarak katı bölgeden sıvı bölgeye geçilirken hangi çizgi kesilir?', 'Erime eğrisi', ['Buhar basıncı eğrisi', 'Süblimleşme eğrisi', 'Üçlü noktadan geçen yatay çizgi'], 'Katı ile sıvı bölgelerini ayıran çizgi erime (katı-sıvı denge) eğrisidir; bu çizgi kesilirken madde erir.'),
  ('Aynı sıcaklıkta bulunan bir gaz örneğindeki taneciklerin hızları için hangisi doğrudur?', 'Tanecikler farklı hızlara sahiptir', ['Bütün tanecikler aynı hızla hareket eder', 'Bütün tanecikler durgundur', 'Tanecik hızları sıcaklıktan tamamen bağımsızdır'], 'Gaz taneciklerinin hızları bir dağılım gösterir; bazıları yavaş, bazıları hızlıdır. Sıcaklık yalnız ortalama kinetik enerjiyi belirler.'),
  ('Mutlak sıfır sıcaklığı için kuramsal olarak ne söylenebilir?', 'Taneciklerin öteleme kinetik enerjisi en düşük düzeydedir', ['Tanecikler en hızlı hâldedir', 'Tüm maddeler gaz hâlindedir', 'Tanecikler en büyük hacmi kaplar ve en hızlı çarpışır'], '0 K (–273,15 °C) en düşük sıcaklık sınırıdır; bu noktada tanecik hareketi kuramsal olarak en düşük enerji düzeyindedir.'),
  ('Bir pistonlu kapta gaz sıcaklığı sabitken sıkıştırıldığında taneciklerin ortalama hızı nasıl değişir?', 'Değişmez', ['Artar', 'Azalır', 'Sıfıra iner ve gaz sıvılaşır'], 'Ortalama hız yalnız sıcaklığa ve mol kütlesine bağlıdır. Sıcaklık sabitken sıkıştırma çarpışma sıklığını artırır ama hızı değiştirmez.'),
  ('Sabit sıcaklıkta belirli miktardaki bir gazın basınç-hacim grafiği nasıl bir eğri verir?', 'Hiperbol', ['Orijinden geçen doğru', 'Yatay doğru', 'Basınç eksenine paralel dikey doğru'], 'P · V sabit olduğundan basınç arttıkça hacim ters orantılı olarak azalır; bu ilişkinin grafiği bir hiperboldür. P ile 1/V grafiği ise orijinden geçen doğrudur.'),
  ('Basınçlı düdüklü tencere kapağındaki emniyet supabının işlevi Gay-Lussac yasasıyla nasıl ilişkilidir?', 'Isınan buharın artan basıncını sınırlar', ['Tencerenin hacmini artırır', 'Suyun donmasını önler', 'Isıtıldıkça basıncı düşürerek kaynamayı engeller'], 'Hacmi sabit tencerede sıcaklık arttıkça basınç yükselir; supap belirli bir basıncın üzerinde açılarak fazla buharı dışarı verir ve tencerenin patlamasını önler.'),
  ('Delinmemiş ama hafifçe ezilmiş bir pinpon topu sıcak suya bırakıldığında eski şeklini alıyor. Bu durumun en iyi açıklaması hangisidir?', 'Isınan içteki havanın basıncının artıp çeperi dışa itmesi', ['Sıcak suyun topun içine girip onu şişirmesi', 'Plastik çeperin sıcakta kütlesinin artması', 'İçteki havanın sıvılaşıp genleşmesi'], 'Topun içindeki hava miktarı sabittir. Isınan havanın basıncı artar ve ezik çeperi dışarı iterek topun yeniden küresel olmasını sağlar.'),
  ('Normal koşullarda 0,5 mol CH₄ ve 1,5 mol He gazlarından oluşan bir karışımın toplam hacmi kaç L\'dir?', '44,8', ['22,4', '33,6', '11,20'], 'Gaz karışımlarında toplam mol sayısı 2 mol\'dür; normal koşullarda 2 · 22,4 = 44,8 L hacim kaplar.'),
  ('0 °C ve 1 atm\'de 2 mol ideal gaz için PV/T oranı yaklaşık kaçtır? (R = 0,082 L·atm/(mol·K))', '0,164', ['0,082', '0,041', '0,0082'], 'PV/T = nR = 2 · 0,082 = 0,164 L·atm/K. Bu oran sıcaklık ve basınçtan bağımsız olarak mol sayısıyla belirlenir.'),
  ('Aynı sıcaklıkta eşit hacimli iki kaptan birinde 4 g He (4 g/mol), diğerinde 32 g O₂ (32 g/mol) vardır. Kaplardaki basınçlar için ne söylenebilir?', 'Eşittir', ['He kabındaki 8 kat büyüktür', 'O₂ kabındaki 8 kat büyüktür', 'O₂ kabındaki 2 kat büyüktür'], 'Her iki kapta da 1 mol gaz bulunur. Aynı sıcaklık ve hacimde basınç yalnız mol sayısına bağlıdır, dolayısıyla basınçlar eşittir.'),
  ('41 L hacimli bir kapta 127 °C\'de 4 atm basınç yapan ideal gaz kaç moldür? (R = 0,082 L·atm/(mol·K))', '5', ['50', '0,5', '0,05'], 'n = PV / RT = 4 · 41 / (0,082 · 400) = 164 / 32,8 = 5 mol.'),
  ('Kütlesi bilinen bir gazın mol kütlesini deneysel olarak bulmak için ideal gaz denkleminden hangi üç büyüklüğün ölçülmesi gerekir?', 'Basınç, hacim ve sıcaklık', ['Renk, koku ve kütle', 'Yoğunluk, renk ve sıcaklık', 'Yalnız hacim ve kütle'], 'PV = (m/M)RT eşitliğinde m, P, V ve T ölçülürse M = mRT / PV hesaplanabilir.'),
  ('Bir gaz karışımında A gazının kısmi basıncı 300 mmHg, B gazınınki 450 mmHg\'dir. A\'nın mol kesri kaçtır?', '0,4', ['0,6', '0,67', '1,5'], 'Toplam basınç 750 mmHg\'dir. Mol kesri kısmi basınç oranına eşittir: 300 / 750 = 0,4.'),
  ('Sabit sıcaklıkta, içinde N₂ ve O₂ bulunan pistonlu bir kabın hacmi iki katına çıkarılırsa N₂\'nin mol kesri nasıl değişir?', 'Değişmez', ['İki katına çıkar', 'Yarıya iner', 'Dört katına çıkar'], 'Hacim değişimi bütün gazların kısmi basınçlarını aynı oranda düşürür; mol sayıları değişmediği için mol kesirleri de aynı kalır.'),
  ('CH₄ (16 g/mol) ve SO₂ (64 g/mol) gazları aynı anda uzun bir borunun iki ucundan bırakılıyor. CH₄\'ün aldığı yolun SO₂\'nin aldığı yola oranı kaçtır?', '2', ['4', '1/2', '1/4'], 'Aynı sürede alınan yollar hızlarla orantılıdır: √(64/16) = √4 = 2. Metan, kükürt dioksitin iki katı yol alır.'),
  ('Bir gazın yayılma hızı aynı gaz için hangi değişiklikle artırılabilir?', 'Sıcaklığı artırmak', ['Sıcaklığı azaltmak', 'Gazı daha ağır izotoplarla yer değiştirmek', 'Kabı soğutup basıncı düşürmek'], 'Sıcaklık arttıkça taneciklerin ortalama hızı artar ve gaz daha hızlı yayılır; Graham yasası aynı sıcaklıktaki gazları karşılaştırır.'),
  ('Amonyak gazının yüksek basınçta ideal davranıştan belirgin sapma göstermesinin başlıca nedeni nedir?', 'Molekülleri arasındaki güçlü çekim kuvvetleri', ['Amonyağın tek atomlu olması', 'Amonyağın renkli olması', 'Amonyak moleküllerinin hiç hacim kaplamaması ve çarpışmaması'], 'Polar NH₃ molekülleri birbirleriyle hidrojen bağı yapabilir. Bu güçlü etkileşimler basıncın ideal gaz denkleminin öngördüğünden düşük çıkmasına yol açar.'),
  ('Bir gazın kritik sıcaklığı –147 °C ise oda sıcaklığında bu gaz için hangisi doğrudur?', 'Yalnız basınç artırılarak sıvılaştırılamaz', ['Basınç artırılınca kolayca sıvılaşır', 'Oda sıcaklığında katıdır', 'Oda sıcaklığında kendiliğinden sıvıya dönüşür'], 'Oda sıcaklığı bu gazın kritik sıcaklığının çok üstündedir; gaz sıvılaştırılmak için önce –147 °C\'nin altına soğutulmalıdır. Azotun kritik sıcaklığı yaklaşık bu değerdedir.'),
  ('Plazma için aşağıdakilerden hangisi yanlıştır?', 'Yalnız nötr atomlardan oluşur', ['Elektriği iletir', 'Manyetik alandan etkilenir', 'İyon ve serbest elektron içerir'], 'Plazma, önemli bir kısmı iyonlaşmış bir gazdır; içinde pozitif iyonlar ve serbest elektronlar bulunur. Yalnız nötr atomlardan oluşan bir gaz plazma değildir.'),
  ('Plazma kesme makinelerinin metalleri kesebilmesi plazmanın hangi özelliğinden yararlanır?', 'Çok yüksek sıcaklığa ulaşabilmesi', ['Suda çözünebilmesi', 'Çok düşük sıcaklıkta olması', 'Katı hâlde bulunup metali aşındırarak kesmesi'], 'Plazma kesicilerde elektrik arkıyla iyonlaştırılan gaz binlerce derece sıcaklığa ulaşır; bu sıcaklık metali eritir, gaz akışı da eriyiği uzaklaştırır.'),
  ('Bir sıvının saf olup olmadığını anlamak isteyen öğrenci sıvıyı kaynatıp sıcaklığı izliyor. Hangi gözlem sıvının karışım olduğunu gösterir?', 'Kaynama sürerken sıcaklığın yavaşça artması', ['Kaynamanın sabit sıcaklıkta sürmesi', 'Sıvının renksiz olması', 'Kaynama boyunca sıvının renksiz ve kokusuz kalması'], 'Saf sıvılar sabit basınçta sabit sıcaklıkta kaynar. Kaynama boyunca sıcaklığın değişmesi bileşimin değiştiğini, yani karışım olduğunu gösterir.'),
  ('Karışımlarla ilgili aşağıdaki ifadelerden hangisi yanlıştır?', 'Bileşenleri yalnız kimyasal yollarla ayrılabilir', ['Bileşenler özelliklerini korur', 'Bileşimi değişken olabilir', 'Belirli bir kimyasal formülle gösterilemez'], 'Karışımların bileşenleri süzme, damıtma, mıknatısla ayırma gibi fiziksel yöntemlerle ayrılabilir. Kimyasal yöntem gerektiren bileşiklerdir.'),
  ('Kükürt tozu ile şeker karışımındaki bileşenleri ayırmak için hangi özellik farkından yararlanmak en uygundur?', 'Sudaki çözünürlük', ['Manyetik özellik', 'Renk', 'Taneciklerin şekli ve rengi'], 'Şeker suda çözünür, kükürt çözünmez. Karışım suyla karıştırılıp süzülünce kükürt süzgeçte kalır; şeker süzüntüden buharlaştırmayla elde edilir.'),
  ('Hangi karışım homojen değildir?', 'Kan', ['Sirke', 'Paslanmaz çelik', 'Kuru hava'], 'Kan, plazma içinde dağılmış hücreler içerir; santrifüjle ayrılabilen bu yapı heterojendir. Sirke, paslanmaz çelik ve kuru hava homojen karışımlardır.'),
  ('Çözelti türleri için verilen eşleştirmelerden hangisi doğrudur?', 'Gaz içinde gaz: hava', ['Sıvı içinde katı: pirinç alaşımı', 'Katı içinde sıvı: gazoz', 'Gaz içinde sıvı: tuzlu su'], 'Hava gaz içinde gaz çözeltisidir. Pirinç katı içinde katı, gazoz sıvı içinde gaz, tuzlu su sıvı içinde katı çözeltisidir.'),
  ('Süt hangi tür karışıma örnektir?', 'Emülsiyon', ['Gerçek çözelti', 'Süspansiyon', 'Gaz içinde sıvı aerosol'], 'Sütte küçük yağ damlacıkları ve proteinler su içinde dağılmıştır; ışığı saçtığı için beyaz ve bulanık görünür.'),
  ('Koloidal bir karışım normal süzgeç kâğıdından süzüldüğünde ne gözlenir?', 'Tanecikler süzgeçten geçer', ['Bütün tanecikler süzgeçte kalır', 'Karışım katılaşır', 'Su süzgeçte kalır, tanecikler geçer'], 'Koloidal tanecikler süzgeç kâğıdının gözeneklerinden küçüktür ve süzgeçten geçer. Ancak çok ince gözenekli zarlarla (diyaliz) ayrılabilirler.'),
  ('Bir öğrenci saydam görünen üç sıvıya karanlıkta lazer tutuyor; yalnız birinde ışın yolu görünüyor. Bu sıvı en olası hangisidir?', 'Seyreltik nişasta-su karışımı', ['Tuzlu su', 'Şekerli su', 'Damıtılmış saf su'], 'Nişasta molekülleri koloidal boyuttadır ve Tyndall etkisi gösterir; tuzlu su, şekerli su ve saf suda ışın yolu görünmez.'),
  ('Uçak gövdelerinde saf alüminyum yerine duralumin gibi alüminyum alaşımlarının kullanılmasının nedeni nedir?', 'Hafifliği korurken çok daha sağlam olması', ['Saf alüminyumdan çok daha ağır olması', 'Elektriği hiç iletmemesi', 'Erime noktasının oda sıcaklığının altında olması'], 'Alüminyuma az miktarda bakır, magnezyum ve manganez eklenmesi, düşük yoğunluğu büyük ölçüde korurken dayanıklılığı önemli ölçüde artırır.'),
  ('Alaşımlar için aşağıdakilerden hangisi doğrudur?', 'Bileşimleri belirli sınırlar içinde değişebilir', ['Her zaman tek bir elementten oluşur', 'Sabit formüllü bileşiklerdir', 'Hiçbir zaman metal içermez, yalnız ametallerden oluşur'], 'Alaşımlar karışım olduğundan bileşenlerinin oranı istenen özelliklere göre ayarlanabilir; örneğin farklı karbon oranlarında farklı çelikler üretilir.'),
  ('Beyaz altının sarı altından farklı renkte olmasının nedeni nedir?', 'Altına nikel, paladyum ya da gümüş gibi beyaz metaller katılması', ['Altının erimiş hâlde bulunması', 'Altının oksijenle tepkimeye girmesi', 'Altının yüzeyinin süblimleşip altındaki gümüşün görünmesi'], 'Beyaz altın, altının paladyum, nikel ya da gümüş gibi metallerle oluşturduğu bir alaşımdır; eklenen metaller sarı rengi bastırır. Çoğu zaman yüzeyi rodyumla kaplanır.'),
  ('Evlerde kullanılan musluk suyu arıtma cihazlarındaki aktif karbon filtrenin işlevi nedir?', 'Sudaki bazı organik maddeleri ve klor kokusunu yüzeyinde tutmak', ['Suyu kaynatmak', 'Suya mineral eklemek', 'Suyu dondurup buz kristallerini süzerek arıtmak'], 'Aktif karbonun çok geniş gözenekli yüzeyi, sudaki pek çok organik molekülü ve klor gibi kokulu maddeleri tutar (adsorpsiyon).'),
  ('Gül yağı ve lavanta yağı gibi uçucu yağların bitkilerden elde edilmesinde kullanılan yöntem hangisidir?', 'Su buharı damıtması', ['Süzme', 'Mıknatısla ayırma', 'Elekten geçirerek eleme'], 'Su buharı bitki dokusundan geçerken uçucu yağları da sürükler; buhar yoğuşturulunca su ile yağ ayrı katmanlar oluşturur ve ayrılır.'),
  ('Bakır(II) sülfat çözeltisinden büyük ve düzgün kristaller elde etmek isteyen bir öğrenci için en uygun yöntem hangisidir?', 'Doymuş çözeltiyi kapağı örtülü olarak günlerce yavaşça buharlaşmaya bırakmak', ['Çözeltiyi hızla kaynatıp tüm suyu uçurmak', 'Çözeltiyi buz banyosunda aniden soğutmak', 'Çözeltiyi süzgeç kâğıdından geçirmek'], 'Çözücünün yavaş uzaklaşması kristallerin düzenli büyümesine fırsat verir. Hızlı buharlaştırma ya da ani soğutma çok sayıda küçük kristal oluşturur.'),
  ('Rf değeri 0,8 olan A maddesi ile 0,3 olan B maddesi için aynı kâğıt kromatografisi deneyinde hangisi doğrudur?', 'A, hareketli fazla daha uzağa taşınmıştır', ['B, hareketli fazda daha iyi çözünür', 'İki madde aynı yolu almıştır', 'B durgun faza daha zayıf tutunduğu için daha hızlı ilerler'], 'Rf değeri büyük olan madde çözücü cephesine daha yakın ilerler; bu, hareketli fazda daha iyi çözündüğünü ve durgun faza zayıf tutunduğunu gösterir.'),
  ('Sütten krema ayrılmasında kullanılan seperatörler (krema makineleri) hangi ilkeye göre çalışır?', 'Dönme hareketiyle yoğunluk farkına göre ayırma', ['Kaynama noktası farkına göre ayırma', 'Mıknatıslanma farkına göre ayırma', 'Taneciklerin renk farkına göre ayırma'], 'Hızla dönen kapta yoğunluğu büyük olan yağsız süt dışa, daha az yoğun olan yağlı krema merkeze doğru toplanır.'),
  ('İyot ile kum karışımından iyodu ayırmak için en uygun yöntem hangisidir?', 'Süblimleştirme', ['Mıknatısla ayırma', 'Eleme', 'Suda çözüp dekantasyon'], 'Karışım ısıtıldığında iyot süblimleşerek buhar hâline geçer, soğuk bir yüzeyde yeniden katılaşır; kum ise kapta kalır.'),
  ('Etil alkol ile suyun her oranda karışabilmesini sağlayan başlıca etkileşim hangisidir?', 'Hidrojen bağı', ['İyon-iyon etkileşimi', 'Metalik bağ', 'Yalnız London kuvvetleri'], 'Etanolün –OH grubu su molekülleriyle hidrojen bağı kurar; benzer türde ve güçte etkileşimler iki sıvının her oranda karışmasını sağlar.'),
  ('Hekzan (C₆H₁₄) ile su karıştırıldığında iki ayrı katman oluşmasının nedeni nedir?', 'Hekzanın sudaki hidrojen bağlarını bozacak etkileşim kuramaması', ['Hekzanın sudan daha yoğun olması', 'Hekzanın suyla tepkimeye girmesi', 'Suyun apolar bir çözücü olup hekzanı dışarı itmesi'], 'Apolar hekzan, su molekülleri arasındaki hidrojen bağlarını bozacak kadar güçlü etkileşim kuramaz. Bu yüzden su molekülleri bir arada kalır ve hekzan ayrı bir katman oluşturur.'),
  ('Bir iyonik katının suda çözünmesi sırasında su moleküllerinin pozitif iyonlara hangi uçlarıyla yöneldiği söylenir?', 'Kısmi negatif yüklü oksijen uçlarıyla', ['Kısmi pozitif yüklü hidrojen uçlarıyla', 'Yüksüz orta kısımlarıyla', 'Rastgele, hiçbir yöne yönelmeden'], 'Su molekülünde oksijen kısmi negatif, hidrojenler kısmi pozitif yüklüdür. Pozitif iyonu oksijen uçları, negatif iyonu hidrojen uçları sarar.'),
  ('20 °C\'de çözünürlüğü 40 g/100 g su olan bir tuzdan 25 g, 20 °C\'de 50 g suya ekleniyor. Dipte kaç g katı kalır?', '5', ['0', '15', '25'], '50 g suda en fazla 40 · 50 / 100 = 20 g çözünür. 25 – 20 = 5 g katı çözünmeden kalır.'),
  ('Çözünürlükleri sıcaklıkla farklı değişen iki tuzdan biri soğutmayla, diğeri buharlaştırmayla daha kolay kristallendirilir. Bu bilgiye göre soğutmayla kristallendirmeye en uygun tuz hangisidir?', 'Çözünürlüğü sıcaklıkla hızla artan tuz', ['Çözünürlüğü sıcaklıkla neredeyse değişmeyen tuz', 'Suda hiç çözünmeyen tuz', 'Çözünürlüğü sıfır olan tuz'], 'Sıcakta çok, soğukta az çözünen tuzun sıcak doymuş çözeltisi soğutulunca büyük miktarda kristal çöker.'),
  ('Sodyum klorürün çözünürlüğü 20 °C\'de 36 g, 100 °C\'de 39 g/100 g sudur. 100 °C\'de 200 g suyla hazırlanmış doymuş NaCl çözeltisi 20 °C\'ye soğutulursa kaç g tuz çöker?', '6', ['3', '36', '78'], '100 °C\'de 2 · 39 = 78 g, 20 °C\'de 2 · 36 = 72 g çözünebilir. Soğutmada 78 – 72 = 6 g tuz çöker.'),
  ('Termik santrallerin sıcak atık sularının akarsulara verilmesinin canlılara zararlı olmasının kimyasal nedeni nedir?', 'Isınan sudaki çözünmüş oksijenin azalması', ['Suyun yoğunluğunun artması', 'Suyun donma noktasının yükselmesi', 'Sudaki tuzların buharlaşması'], 'Gazların sudaki çözünürlüğü sıcaklıkla azalır. Isıl kirlilik, çözünmüş oksijeni düşürerek balıklar gibi suda yaşayan canlıları olumsuz etkiler.'),
  ('25 °C\'de 1 atm CO₂ basıncında CO₂\'nin sudaki çözünürlüğü yaklaşık 0,034 mol/L\'dir. Aynı sıcaklıkta CO₂ basıncı 4 atm olursa çözünürlük yaklaşık kaç mol/L olur?', '0,136', ['0,0085', '0,034', '0,544'], 'Henry yasasına göre çözünürlük kısmi basınçla doğru orantılıdır: 0,034 · 4 = 0,136 mol/L.'),
  ('Musluktan bardağa doldurulan soğuk su bir süre oda sıcaklığında bekletildiğinde bardağın iç çeperinde küçük kabarcıkların oluşmasının nedeni nedir?', 'Isınan suda çözünmüş havanın çözünürlüğünün azalması', ['Suyun oda sıcaklığında kaynaması', 'Bardağın suyla tepkimeye girmesi', 'Suyun içindeki tuzların gaza dönüşmesi'], 'Su ısındıkça içinde çözünmüş olan hava gazlarının çözünürlüğü azalır; fazla gaz çeperlerde kabarcıklar hâlinde ayrılır.'),
  ('Doymuş bir çözeltide dinamik denge için hangisi doğrudur?', 'Çözünme ve kristallenme aynı hızla sürer', ['Çözünme tamamen durmuştur', 'Kristallenme hiç olmaz', 'Dipteki katının kütlesi sürekli azalır'], 'Doymuş çözeltide dipteki katıdan sürekli tanecik çözünür, çözeltiden de aynı hızla tanecik katıya döner; bu yüzden dipteki katı miktarı değişmez.'),
  ('Doymuş bir KNO₃ çözeltisi (çözünürlüğü sıcaklıkla artar) dipte katı olmadan ısıtılırsa çözelti ne hâle gelir?', 'Doymamış', ['Aşırı doymuş', 'Doymuş kalır', 'Çökelti oluşur'], 'Isıtınca çözünürlük artar ama çözünen miktarı değişmez; çözelti artık daha fazla çözünen alabileceği için doymamış hâle geçer.'),
  ('Bir tuzun doymamış çözeltisini doymuş hâle getirmek için hangi işlem her zaman işe yarar?', 'Aynı tuzdan eklemek', ['Çözeltiye su eklemek', 'Çözeltiyi karıştırmak', 'Çözeltiyi başka bir kaba aktarmak'], 'Aynı tuzdan eklenmeye devam edilirse çözünürlük sınırına ulaşılır. Sıcaklık değiştirme yöntemi tuzun çözünürlüğünün sıcaklıkla nasıl değiştiğine bağlıdır.'),
  ('Kütlece %30\'luk 400 g şeker çözeltisine kaç g su eklenirse çözelti kütlece %20\'lik olur?', '200', ['100', '120', '133,3'], 'Şeker kütlesi 400 · 0,30 = 120 g\'dır. %20\'lik çözelti 120 / 0,20 = 600 g olmalıdır; eklenecek su 600 – 400 = 200 g.'),
  ('Hacimce %20\'lik 250 mL alkol çözeltisine 250 mL su eklenirse yeni çözeltinin hacimce yüzdesi yaklaşık kaç olur? (Hacimlerin toplanabildiği kabul edilecek.)', '%10', ['%20', '%40', '%12,5'], 'Alkol hacmi 250 · 0,20 = 50 mL\'dir. Toplam hacim 500 mL olunca 50 / 500 · 100 = %10.'),
  ('Bir su örneğinin her litresinde 0,05 mg kurşun bulunuyor. Suyun yoğunluğu 1 g/mL kabul edilirse kurşun derişimi kaç ppm\'dir?', '0,05', ['0,5', '50', '0,005'], '1 L su yaklaşık 1 kg\'dır; 1 ppm = 1 mg/kg olduğundan 0,05 mg/kg = 0,05 ppm.'),
  ('ppb (milyarda bir) birimi ppm\'e göre nasıldır?', '1 ppm = 1000 ppb', ['1 ppb = 1000 ppm', '1 ppm = 1 ppb', '1 ppm = 1 000 000 ppb'], 'ppm 10⁶\'da bir, ppb 10⁹\'da birdir; bu yüzden 1 ppm, 1000 ppb\'ye eşittir. ppb çok eser miktarlar için kullanılır.'),
  ('Aynı hacimdeki 1 M glikoz ve 1 M NaCl çözeltileri için hangisi doğrudur?', 'Çözünen formül birimi sayıları eşittir', ['Toplam tanecik sayıları eşittir', 'Çözünen kütleleri eşittir', 'İkisi de elektriği eşit derecede iletir'], 'Molarite ve hacim aynı olduğundan çözünen formül birimi (mol) sayısı eşittir. Ancak NaCl iyonlaştığı için tanecik sayısı iki katıdır ve mol kütleleri farklı olduğu için kütleler de farklıdır.'),
  ('Erimiş hâldeki sofra tuzunun elektriği iletmesi ile tuzlu suyun elektriği iletmesinin ortak nedeni nedir?', 'Her ikisinde de serbestçe hareket edebilen iyonların bulunması', ['Her ikisinde de serbest elektron bulunması', 'Her ikisinin de sıvı metal olması', 'Her ikisinin de yalnız kovalent moleküller içerip iyon barındırmaması'], 'Eriyikte ve sulu çözeltide Na⁺ ve Cl⁻ iyonları serbestçe hareket eder; akımı bu iyonlar taşır. Katı NaCl\'de ise iyonlar sabit olduğu için iletkenlik yoktur.'),
  ('Eşit derişimli HCl ve CH₃COOH (asetik asit) çözeltilerinden HCl\'nin elektriği daha iyi iletmesinin nedeni nedir?', 'HCl\'nin tamamen, asetik asidin kısmen iyonlaşması', ['Asetik asidin hiç çözünmemesi', 'HCl\'nin serbest elektron içermesi', 'Asetik asidin daha az yoğun olup suyun üstünde kalması'], 'HCl kuvvetli elektrolittir ve suda neredeyse tamamen iyonlaşır. Asetik asit zayıf elektrolittir; moleküllerinin yalnız küçük bir kısmı iyonlaşır.'),
  ('Aynı sıcaklıkta saf su, 0,1 m şeker çözeltisi ve 0,1 m KCl çözeltisinin buhar basınçlarının büyükten küçüğe sıralaması hangisidir?', 'Saf su > şeker çözeltisi > KCl çözeltisi', ['KCl çözeltisi > şeker çözeltisi > saf su', 'Şeker çözeltisi > saf su > KCl çözeltisi', 'Üçü eşittir'], 'Çözünen tanecik sayısı arttıkça buhar basıncı düşer. KCl iki iyon verdiği için tanecik derişimi şekerinkinin iki katıdır; en düşük buhar basıncı ondadır.'),
  ('Deniz suyuyla ıslanan çamaşırların tatlı suyla ıslananlara göre daha geç kurumasının bir nedeni nedir?', 'Tuzlu suyun buhar basıncının daha düşük olması', ['Tuzlu suyun buhar basıncının daha yüksek olması', 'Tuzun suyu dondurması', 'Deniz suyunun hiç buharlaşmaması'], 'Çözünmüş tuzlar suyun buhar basıncını düşürür; bu da buharlaşma hızını azaltır.'),
  ('1 atm\'de 100,26 °C\'de kaynayan bir glikoz çözeltisinin molalitesi kaçtır? (Kk = 0,52 °C/m)', '0,5', ['0,26', '1', '0,135'], 'ΔTk = 0,26 °C = 0,52 · m eşitliğinden m = 0,5 mol/kg.'),
  ('Kaynama noktası yükselmesi neden koligatif bir özelliktir?', 'Çözünenin türüne değil tanecik derişimine bağlı olduğu için', ['Yalnız renkli çözünenlerde görüldüğü için', 'Çözücünün türünden bağımsız olduğu için', 'Yalnız gaz çözeltilerinde gerçekleştiği için'], 'Koligatif özellikler, çözünenin kimliğinden bağımsız olarak çözeltideki tanecik sayısına bağlıdır. Kk sabiti ise çözücüye özgüdür.'),
  ('1 kg suda çözüldüğünde donma noktasını –3,72 °C\'ye düşüren bir molekül çözünenden (iyonlaşmayan) kaç mol kullanılmıştır? (Kd = 1,86 °C/m)', '2', ['1', '3,72', '0,5'], 'ΔTd = 3,72 = 1,86 · m · 1 ve m = 2 mol/kg. Çözücü 1 kg olduğundan 2 mol çözünen vardır.'),
  ('Kar ve buzla kaplı uçak kanatlarının kalkıştan önce glikol içeren çözeltilerle yıkanmasının amacı nedir?', 'Buzu eritip yeniden donmasını geciktirmek', ['Kanatları ağırlaştırmak', 'Kanatları boyamak', 'Kanatların hava ile sürtünmesini artırarak kaldırmayı kolaylaştırmak'], 'Sıcak glikol-su çözeltisi buzu eritir; ayrıca yüzeyde kalan çözeltinin donma noktası düşük olduğu için yeniden buzlanma gecikir.'),
  ('Suda eşit molalitede hazırlanan aşağıdaki çözeltilerden hangisinde donma noktası alçalması en büyüktür?', 'Fe(NO₃)₃', ['Glikoz', 'KBr', 'Üre'], 'Fe(NO₃)₃ suda bir Fe³⁺ ve üç NO₃⁻ iyonu, yani dört tanecik verir. KBr iki, glikoz ve üre birer tanecik verir.'),
  ('Ozmotik basınç için aşağıdakilerden hangisi doğrudur?', 'Osmozu durdurmak için çözelti tarafına uygulanması gereken basınçtır', ['Çözeltinin buhar basıncına eşittir', 'Saf suyun yaptığı atmosfer basıncıdır', 'Çözünenin kütlesine bağlı değildir, yalnız sıcaklığa bağlıdır'], 'Ozmotik basınç, yarı geçirgen zardan çözücünün net geçişini durdurmak için çözeltiye uygulanması gereken basınçtır; π = MRTi ile hesaplanır.'),
  ('Bitkilere fazla gübre verildiğinde yapraklarının solmasının nedeni nedir?', 'Topraktaki çözeltinin derişikleşmesiyle köklerin osmozla su kaybetmesi', ['Gübrenin suyu dondurması', 'Gübrenin bitkiyi ısıtması', 'Köklerin gübreyi gaz hâline getirip yapraklara taşıması'], 'Fazla gübre topraktaki suyu kök hücrelerinden daha derişik hâle getirir; su osmozla hücrelerden toprağa geçer ve bitki susuz kalır.'),
  ('Aynı sıcaklıkta 0,1 M NaCl ve 0,1 M glikoz çözeltilerinin ozmotik basınçları için ne söylenebilir?', 'NaCl çözeltisininki yaklaşık iki katıdır', ['Glikozunki yaklaşık iki katıdır', 'İkisi tam olarak eşittir', 'NaCl iyonlaştığı için ozmotik basıncı sıfırdır'], 'Ozmotik basınç tanecik derişimiyle orantılıdır. NaCl iki iyona ayrıştığından aynı molaritede yaklaşık iki kat ozmotik basınç oluşturur.'),
  ('Tatlı su balıklarının deniz suyuna konduğunda kısa sürede ölmesinin osmozla ilgili açıklaması nedir?', 'Vücutlarındaki suyun derişik deniz suyuna geçmesi', ['Deniz suyunun vücutlarına aşırı su pompalaması', 'Deniz suyunun daha soğuk olması', 'Deniz suyunda hiç çözünmüş oksijen bulunmaması'], 'Deniz suyu tatlı su balığının vücut sıvılarından çok daha derişiktir; su osmozla vücuttan dışarı çıkar ve balık su kaybeder.'),
  ('Silisyum karbür (SiC) çok serttir, çok yüksek sıcaklıkta erir ve zımpara yapımında kullanılır. Bu özellikler SiC\'nin hangi katı türünde olduğunu düşündürür?', 'Kovalent ağ katısı', ['Moleküler katı', 'Metalik katı', 'Amorf moleküler katı'], 'Atomların üç boyutta kovalent bağlarla bağlandığı ağ yapısı, elmas gibi SiC\'ye de yüksek sertlik ve yüksek erime noktası kazandırır.'),
  ('Aşağıdaki katılardan hangisi erimiş hâlde de katı hâlde de elektriği iletir?', 'Bakır', ['Sodyum klorür', 'Şeker', 'Kükürt'], 'Metallerde serbest elektronlar her iki hâlde de bulunduğu için bakır katı ve sıvı hâlde iletkendir. NaCl yalnız erimiş ya da çözünmüş hâlde iletir.'),
  ('Suyun yüzey geriliminin pek çok sıvıdan yüksek olmasının nedeni nedir?', 'Moleküller arasındaki güçlü hidrojen bağları', ['Su moleküllerinin çok ağır olması', 'Suyun iyonik bir sıvı olması', 'Suyun buhar basıncının diğer sıvılardan çok daha yüksek olması'], 'Yüzeydeki su molekülleri içerideki komşularına hidrojen bağlarıyla güçlü biçimde çekilir; bu güçlü çekim yüksek yüzey gerilimine yol açar.'),
  ('Suyun \'evrensel çözücü\' olarak anılmasının başlıca nedeni nedir?', 'Polar yapısıyla pek çok iyonik ve polar maddeyi çözebilmesi', ['Bütün maddeleri çözebilmesi', 'Apolar olması', 'Apolar yağları ve mumları çok iyi çözebilmesi'], 'Su molekülünün polar olması ve hidrojen bağı kurabilmesi, tuzlar, şekerler ve pek çok polar molekül gibi çok çeşitli maddeleri çözmesini sağlar; ancak apolar yağları iyi çözmez.'),
  ('Okyanuslardaki suyun yüksek özgül ısısı küresel iklim açısından nasıl bir rol oynar?', 'Büyük ısı miktarlarını depolayıp sıcaklık değişimlerini yumuşatır', ['Dünya\'nın hızla ısınmasına yol açar', 'Gece sıcaklıklarını sıfırın çok altına düşürür', 'İklim üzerinde ölçülebilir hiçbir etkisi bulunmaz'], 'Okyanuslar sıcaklıkları fazla değişmeden çok büyük miktarda ısıyı soğurabilir ve taşıyabilir; bu, gezegenin sıcaklık dalgalanmalarını dengeler.'),
  ('Kışın kalın kıyafetlerin vücudu sıcak tutmasında kumaş lifleri arasında hapsolan havanın rolü nedir?', 'Havanın ısıyı kötü iletmesi', ['Havanın ısı üretmesi', 'Havanın sıvılaşması', 'Havanın vücuda sürekli nem vermesi'], 'Gazlarda tanecikler birbirinden uzak olduğu için ısı iletimi zayıftır; lifler arasında hareketsiz kalan hava iyi bir yalıtkan katman oluşturur.'),
  ('Aynı sıcaklıkta suda çözünürlükleri farklı olan iki tuz için hangi bilgi çözünürlüğün ayırt edici özellik olduğunu gösterir?', 'Belirli sıcaklıkta her saf maddenin kendine özgü çözünürlük değeri vardır', ['Bütün tuzların çözünürlüğü aynıdır', 'Çözünürlük yalnız kap büyüklüğüne bağlıdır', 'Çözünürlük yalnız karıştırma hızına ve kabın şekline bağlıdır'], 'Belirli sıcaklık ve basınçta, belirli bir çözücüdeki çözünürlük maddeye özgüdür; bu nedenle madde tanımada ayırt edici özellik olarak kullanılabilir.'),
];
